import 'dart:async';

import 'package:flutter/material.dart';

final appMessengerKey = GlobalKey<ScaffoldMessengerState>();

/// Stand-in for the MQTT ACK coming back from the ESP.
/// TODO: replace with a real wait on the MQTT ack topic (return false on timeout/NACK).
class EspAck {
  EspAck._();

  static Duration delay = const Duration(milliseconds: 600);

  static Future<bool> wait(String command) async {
    debugPrint('[MQTT] gửi lệnh "$command", chờ ACK từ ESP...');
    if (delay > Duration.zero) await Future<void>.delayed(delay);
    return true;
  }
}

/// Backend CRUD requests. Each call only logs on screen for now;
/// TODO: perform the real Supabase/REST request in [_send].
class CrudApi {
  CrudApi._();

  static Future<void> _send(
    String action,
    Map<String, Object?> body, {
    required String when,
  }) async {
    final text = '[CRUD] $action\nKhi: $when\n$body';
    debugPrint(text);
    final messenger = appMessengerKey.currentState;
    if (messenger == null) return;
    messenger
      ..clearSnackBars()
      ..showSnackBar(
        SnackBar(
          content: Text(text),
          duration: const Duration(seconds: 4),
          behavior: SnackBarBehavior.floating,
        ),
      );
  }

  /// Runs [crud] only after the ESP acknowledges [command] over MQTT.
  static Future<void> afterAck(String command, VoidCallback crud) async {
    if (await EspAck.wait(command)) crud();
  }

  // Devices
  static Future<void> addDevice({
    required String userId,
    required String deviceMacAddress,
    required String defaultName,
    required int maxSensorCount,
    required int maxLoadCount,
    required int activeSensorCount,
    required String internetMethod,
  }) => _send(
    'CREATE device',
    {
      'user_id': userId,
      'device_mac_address': deviceMacAddress,
      'default_name': defaultName,
      'max_sensor_count': maxSensorCount,
      'max_load_count': maxLoadCount,
      'active_sensor_count': activeSensorCount,
      'internet_method': internetMethod,
    },
    when: 'nhận thông số thiết bị từ ESP',
  );

  static Future<void> renameDevice(String deviceId, String name) => _send(
    'UPDATE device (đổi tên)',
    {'device_id': deviceId, 'name': name},
    when: 'nhận MQTT ACK đổi tên thiết bị (không cần nhấn Lưu)',
  );

  static Future<void> deleteDevice(String deviceId) => _send(
    'DELETE device',
    {'device_id': deviceId},
    when: 'người dùng nhấn Đồng ý xóa thiết bị',
  );

  // Sensors
  static Future<void> addSensor(Map<String, Object?> sensor) => _send(
    'CREATE sensor',
    sensor,
    when: 'nhấn Lưu cấu hình + nhận MQTT ACK',
  );

  static Future<void> updateSensor(
    Map<String, Object?> sensor, {
    required String when,
  }) => _send('UPDATE sensor', sensor, when: when);

  static Future<void> deleteSensor(String sensorId) => _send(
    'DELETE sensor',
    {'sensor_id': sensorId},
    when: 'người dùng nhấn Đồng ý xóa cảm biến',
  );

  // Loads
  static Future<void> renameLoad(int loadId, String name) => _send(
    'UPDATE load (đổi tên)',
    {'load_id': loadId, 'name': name},
    when: 'nhận MQTT ACK đổi tên tải (không cần nhấn Lưu)',
  );

  static Future<void> setLoadEnabled(int loadId, bool enabled) => _send(
    'UPDATE load (cho phép tải)',
    {'load_id': loadId, 'enabled': enabled},
    when: 'nhận MQTT ACK nút Cho phép tải (không cần nhấn Lưu)',
  );

  static Future<void> updateLoadDelay({
    required int loadId,
    required int delayMinute,
    required String action,
    required int duration,
    required bool isActive,
  }) => _send(
    'UPDATE load_delay_time',
    {
      'load_id': loadId,
      'delay_minute': delayMinute,
      'action': action,
      'duration': duration,
      'is_active': isActive,
    },
    when: 'nhấn Gửi yêu cầu + nhận MQTT ACK',
  );

  // Timers
  static Future<void> addTimer(Map<String, Object?> timer) => _send(
    'CREATE timer',
    timer,
    when: 'nhấn Thêm lịch hẹn + nhận MQTT ACK (không cần nhấn Lưu)',
  );

  static Future<void> updateTimer(
    Map<String, Object?> timer, {
    required String when,
  }) => _send('UPDATE timer', timer, when: when);

  static Future<void> deleteTimer(String timerId) => _send(
    'DELETE timer',
    {'timer_id': timerId},
    when: 'nhận MQTT ACK xóa lịch hẹn (không cần nhấn Lưu)',
  );

  // Automation conditions
  static Future<void> addCondition(Map<String, Object?> condition) => _send(
    'CREATE automation_condition',
    condition,
    when: 'nhấn Thêm điều kiện + nhận MQTT ACK (không cần nhấn Áp dụng)',
  );

  static Future<void> updateCondition(
    Map<String, Object?> condition, {
    required String when,
  }) => _send('UPDATE automation_condition', condition, when: when);

  static Future<void> deleteCondition(String conditionId) => _send(
    'DELETE automation_condition',
    {'condition_id': conditionId},
    when: 'nhận MQTT ACK xóa điều kiện (không cần nhấn Áp dụng)',
  );
}

