#ifndef MAIN_DATA_TYPES_H
#define MAIN_DATA_TYPES_H

#include <stdint.h>
#include <stdbool.h>

#include "freertos/FreeRTOS.h"
#include "freertos/event_groups.h"
#include "freertos/queue.h"
#include "freertos/semphr.h"

#include "app_pins.h"

#define APP_SENSOR_COUNT APP_SENSOR_INTERFACE_COUNT

/* 1. Network interface */
typedef enum {
    NET_IF_NONE = 0,
    NET_IF_ETH,
    NET_IF_WIFI
} net_interface_t;

/* 2. System error bitmask */
typedef enum {
    SYS_ERR_NONE = 0,
    SYS_ERR_MODBUS_TIMEOUT = (1 << 0),
    SYS_ERR_NET_LOST = (1 << 1),
    SYS_ERR_MQTT_BROKER = (1 << 2),
    SYS_ERR_NVM_FAIL = (1 << 3),
    SYS_ERR_SENSOR_OUT_RANGE = (1 << 4)
} sys_error_code_t;

/* 3. System state machine */
typedef enum {
    STATE_INIT = 0,
    STATE_BLE_PROV,
    STATE_NET_CONNECTING,
    STATE_OPERATIONAL,
    STATE_FAILOVER,
    STATE_FACTORY_RESET,
    STATE_MQTT_CONNECTING,  /* network up, MQTT not yet connected */
    STATE_NET_LOST,         /* no interface has WAN */
    STATE_BLE_PROV_RUNTIME  /* BLE provisioning while the system keeps running */
} sys_state_t;

/* Commands for net_mgmt_task, sent through g_sys.net_cmd_queue */
typedef enum {
    NET_CMD_NONE = 0,
    NET_CMD_START_BLE_PROV_RUNTIME,
    NET_CMD_FACTORY_RESET
} net_cmd_t;

/* 4. Event bits in sys_event_group */
#define BIT_NET_ETH_CONNECTED   (1U << 0)
#define BIT_NET_WIFI_CONNECTED  (1U << 1)
#define BIT_MQTT_CONNECTED      (1U << 2)
#define BIT_PROV_DONE           (1U << 3)
#define BIT_CONFIG_RELOAD       (1U << 4)
#define BIT_NET_ACTIVE_READY    (1U << 5)  /* active interface has IP and WAN OK */
#define BIT_NET_STANDBY_READY   (1U << 6)  /* other interface has IP and a fresh WAN OK */
#define BIT_SYS_NET_LOST        (1U << 7)  /* no interface has WAN */
#define BIT_NET_ETH_WAN_OK      (1U << 8)
#define BIT_NET_WIFI_WAN_OK     (1U << 9)
#define BIT_TIME_VALID          (1U << 10) /* SNTP has synchronised the clock */
#define BIT_SYS_INTERLOCK_TRIPPED (1U << 11) /* safety interlock forced all loads off */
#define BIT_PROV_RESULT_SENT    (1U << 12) /* app has read the provisioning result over BLE */
#define BIT_SYS_ESTOP            (1U << 13) /* latched emergency stop */

/* 5. Modbus sensor configuration */
typedef enum {
    SENSOR_SHT40 = 0,
    SENSOR_DO = 1,
    SENSOR_PH = 2,
    SENSOR_ANALOG_4_20MA = 3
} sensor_type_t;

typedef enum {
    SENSOR_INTERFACE_RS485 = 0,
    SENSOR_INTERFACE_ANALOG_4_20MA = 1
} sensor_interface_type_t;

typedef struct {
    uint8_t slave_id;       /* 1-247 */
    sensor_type_t sensor_type;
    char name[32];
    bool enabled;
    float calib_offset;
} modbus_sensor_cfg_t;

typedef struct {
    char name[32];
    bool enabled;
    float calib_offset;
} analog_4_20ma_sensor_cfg_t;

typedef enum {
    SENSOR_CONDITION_LT = 0,
    SENSOR_CONDITION_LTE,
    SENSOR_CONDITION_EQ,
    SENSOR_CONDITION_GTE,
    SENSOR_CONDITION_GT
} sensor_condition_operator_t;

typedef struct {
    bool enabled;
    uint8_t sensor_id;  /* 1..APP_SENSOR_INTERFACE_COUNT */
    sensor_condition_operator_t op;
    float threshold;
} load_sensor_condition_t;

typedef struct {
    bool enabled;
    bool schedule_enabled;
    uint8_t days_mask;          /* bit 0 Monday through bit 6 Sunday */
    uint16_t on_minute_utc;     /* minutes since 00:00 UTC, 0..1439 */
    uint16_t off_minute_utc;    /* minutes since 00:00 UTC, 0..1439 */
    load_sensor_condition_t on_condition;
    load_sensor_condition_t off_condition;
} load_control_cfg_t;

/* 6. Persistent configuration (NVS namespace "app_cfg") */
typedef struct {
    char wifi_ssid[33];
    char wifi_password[64];
    char user_id[32];
    bool only_use_ethernet;

    modbus_sensor_cfg_t rs485_cfg[APP_RS485_INTERFACE_COUNT];
    analog_4_20ma_sensor_cfg_t analog_4_20ma_cfg[APP_ANALOG_4_20MA_INTERFACE_COUNT];

    char load_name[APP_LOAD_COUNT][32];  /* 4 relays; spec only listed load_1_name */
    load_control_cfg_t load_control[APP_LOAD_COUNT];
    uint32_t safety_timeout_s;
} app_config_t;

/* Legacy scalar sample retained for modules not yet migrated to sensor_cycle_t. */
typedef struct {
    float temperature;
    float humidity;
    bool sht40_valid;

    float do_mg_l;
    bool do_valid;

    float ph_val;
    bool ph_valid;

    int64_t timestamp;
} sensor_data_t;

typedef enum {
    ORIGIN_INTERNAL = 0,
    ORIGIN_MQTT,
    ORIGIN_BLE
} cmd_origin_t;

typedef enum {
    LOAD_COMMAND_SET_STATE = 0,
    LOAD_COMMAND_TIMED_CYCLE,
    LOAD_COMMAND_SET_ALL_OFF,
    LOAD_COMMAND_EMERGENCY_STOP,
    LOAD_COMMAND_EMERGENCY_RELEASE
} load_command_kind_t;

typedef enum {
    LOAD_CYCLE_NONE = 0,
    LOAD_CYCLE_ON_THEN_OFF,
    LOAD_CYCLE_OFF_THEN_ON
} load_cycle_mode_t;

typedef enum {
    LOAD_CYCLE_PHASE_IDLE = 0,
    LOAD_CYCLE_PHASE_WAIT_FIRST,
    LOAD_CYCLE_PHASE_WAIT_SECOND
} load_cycle_phase_t;

typedef struct {
    bool output;
    int64_t auto_off_deadline_us;
    load_cycle_mode_t cycle_mode;
    load_cycle_phase_t cycle_phase;
    int64_t cycle_deadline_us;
    uint16_t cycle_delay_min;
    uint16_t cycle_duration_min;
    int64_t last_sched_minute;
    uint32_t remaining_s;
    uint8_t cycle_next;
} load_runtime_t;

typedef enum {
    SENSOR_SAMPLE_ERROR_NONE = 0,
    SENSOR_SAMPLE_ERROR_TIMEOUT,
    SENSOR_SAMPLE_ERROR_CRC,
    SENSOR_SAMPLE_ERROR_OUT_OF_RANGE,
    SENSOR_SAMPLE_ERROR_NOT_READY,
    SENSOR_SAMPLE_ERROR_DISABLED_MID_CYCLE,
    SENSOR_SAMPLE_ERROR_STOPPED,
    SENSOR_SAMPLE_ERROR_DISABLED,
    SENSOR_SAMPLE_ERROR_MODBUS_EXCEPTION,
    SENSOR_SAMPLE_ERROR_PROTOCOL,
    SENSOR_SAMPLE_ERROR_OFFLINE
} sensor_sample_error_t;

typedef struct {
    uint8_t interface_type;
    uint8_t interface_index;
    uint8_t sensor_type;
    uint8_t valid;
    uint8_t error;
    float v1;
    float v2;
    float v3;
} sensor_sample_t;

typedef struct {
    uint32_t seq;
    int64_t ts_ms;
    uint32_t uptime_ms;
    uint8_t count;
    sensor_sample_t s[APP_SENSOR_INTERFACE_COUNT];

