             (c == 0xe0U && second < 0xa0U) || (c == 0xedU && second >= 0xa0U) ||
             (c == 0xf0U && second < 0x90U) || (c == 0xf4U && second > 0x8fU)) return false;
         for (unsigned j = 2; j <= need; j++)
