 bool mqtt_proto_valid_cmd_id(const char *cmd_id)
 {
     if (cmd_id == NULL) return false;
     size_t len = strlen(cmd_id);
     if (len == 0U || len > CMD_ID_MAX) return false;
     for (size_t i = 0; i < len; i++) {
