enum MqttDeviceTopicKind { telemetry, commands, ack, set, status }

class MqttDeviceTopics {
  const MqttDeviceTopics._(this.base);

  factory MqttDeviceTopics.forDevice({
    required String userId,
    required String deviceId,
  }) {
    _validateSegment(userId, 'userId');
    _validateSegment(deviceId, 'deviceId');
    return MqttDeviceTopics._('v1/users/$userId/devices/$deviceId');
  }

  final String base;

  String get telemetry => '$base/telemetry';
  String get commands => '$base/commands';
  String get ack => '$base/ack';
  String get set => '$base/set';
  String get status => '$base/status';

  static MqttDeviceTopicKind? kindFromTopic(String topic) {
    for (final kind in MqttDeviceTopicKind.values) {
      if (topic.endsWith('/${kind.name}')) return kind;
    }
    return null;
  }

  static String? deviceIdFromTopic(String topic, {required String userId}) {
    final prefix = 'v1/users/$userId/devices/';
    if (!topic.startsWith(prefix)) return null;
    final remainder = topic.substring(prefix.length);
    final separator = remainder.indexOf('/');
    if (separator <= 0 || remainder.indexOf('/', separator + 1) != -1) {
      return null;
    }
    final deviceId = remainder.substring(0, separator);
    if (kindFromTopic(topic) == null) return null;
    return deviceId;
  }

  static void _validateSegment(String value, String name) {
    if (value.trim().isEmpty ||
        value.contains('/') ||
        value.contains('+') ||
        value.contains('#')) {
      throw ArgumentError.value(value, name, 'Invalid MQTT topic segment');
    }
  }
}

