    summary: 'Payload status chưa có mẫu',
    topic: '$_basePath/status',
  ),
  _LogEntry(
    time: '09:39:58',
    direction: 'RX',
    channel: 'MQTT',
    type: 'Telemetry',
    hint: 'V1/…/telemetry',
    summary: 'Payload telemetry chờ firmware chốt',
    topic: '$_basePath/telemetry',
  ),
  _LogEntry(
    time: '09:40:20',
    direction: 'TX',
    channel: 'MQTT',
    type: 'Config',
    hint: 'v1/…/config/set · sensor-config',
    topic: '$_basePath/config/set',
    payload: {
      'sensor_type': 'ph',
