      'name': 'pH_Tank_A1',
      'enabled': true,
      'calib_offset': -0.15,
    },
  ),
  _LogEntry(
    time: '09:41:05',
    direction: 'TX',
    channel: 'MQTT',
    type: 'Command',
    hint: 'v1/…/commands · load-ctrl',
    summary: 'SET_STATE · Load 1 · 60 giây',
    topic: '$_basePath/commands',
    payload: {
      'action': 'SET_STATE',
      'load_id': 1,
      'state': true,
      'duration_sec': 60,
      'new_name': 'Pump_Water_A',
    },
  ),
  _LogEntry(
