            'Xóa',
            style: AppTextStyles.buttonPrimary.copyWith(
              color: AppColors.textSecondary,
            ),
          ),
          style: TextButton.styleFrom(
            foregroundColor: AppColors.textSecondary,
            minimumSize: const Size(0, 44),
          ),
        ),
        TextButton.icon(
          onPressed: onAutoScroll,
          icon: Icon(
            autoScroll
                ? Icons.check_box_rounded
                : Icons.check_box_outline_blank_rounded,
            size: 20,
          ),
          label: const Text('Tự cuộn', style: AppTextStyles.buttonPrimary),
          style: TextButton.styleFrom(
            foregroundColor: AppColors.primary,
            minimumSize: const Size(0, 44),
          ),
        ),
      ],
    );
  }
}

class _ConsolePanel extends StatelessWidget {
  const _ConsolePanel({
    required this.entries,
    required this.selected,
    required this.onSelect,
  });

  final List<_LogEntry> entries;
  final _LogEntry? selected;
  final ValueChanged<_LogEntry> onSelect;

  @override
  Widget build(BuildContext context) {
    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: AppColors.console,
        borderRadius: BorderRadius.circular(18),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              const Expanded(
                child: Text(
                  'BẢN TIN MẪU · MQTT / BLE',
                  style: AppTextStyles.consoleTitle,
                ),
              ),
              Text('${entries.length} mục', style: AppTextStyles.consoleSub),
            ],
          ),
          const SizedBox(height: 10),
          const Divider(height: 1, color: AppColors.consoleDivider),
          const SizedBox(height: 6),
          if (entries.isEmpty)
            const Padding(
              padding: EdgeInsets.symmetric(vertical: 24),
              child: Center(
                child: Text('Không có bản tin', style: AppTextStyles.consoleSub),
              ),
