          else
            for (final e in entries)
              _ConsoleRow(
                entry: e,
                selected: e == selected,
                onTap: () => onSelect(e),
              ),
        ],
      ),
    );
  }
}

class _ConsoleRow extends StatelessWidget {
  const _ConsoleRow({
    required this.entry,
    required this.selected,
    required this.onTap,
  });

  final _LogEntry entry;
  final bool selected;
  final VoidCallback onTap;

  @override
  Widget build(BuildContext context) {
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 4),
      child: Material(
        color: selected ? AppColors.consoleSelected : Colors.transparent,
        borderRadius: BorderRadius.circular(10),
        child: InkWell(
          onTap: onTap,
          borderRadius: BorderRadius.circular(10),
          child: SizedBox(
            width: double.infinity,
            child: Padding(
              padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 8),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(entry.header, style: AppTextStyles.consoleMeta),
                  const SizedBox(height: 2),
                  Text(entry.hint, style: AppTextStyles.consoleSub),
                  const SizedBox(height: 2),
                  Text(entry.preview, style: AppTextStyles.consoleBody),
                ],
              ),
            ),
          ),
        ),
      ),
    );
  }
}

class _DetailCard extends StatelessWidget {
  const _DetailCard({required this.entry});

  final _LogEntry entry;

  @override
  Widget build(BuildContext context) {
    return AppCard(
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Expanded(
                child: Text(
                  'Chi tiết · ${entry.type}',
                  style: AppTextStyles.cardTitle.copyWith(
                    color: AppColors.primary,
                    fontSize: 18,
                  ),
                ),
              ),
              Text(
                '${entry.time}  ·  ${entry.direction}',
                style: AppTextStyles.monoCaption,
              ),
            ],
          ),
          const SizedBox(height: 10),
          Text(entry.topic, style: AppTextStyles.monoCaption),
          if (entry.prettyPayload != null) ...[
            const SizedBox(height: 12),
            Container(
              width: double.infinity,
              padding: const EdgeInsets.all(16),
              decoration: BoxDecoration(
                color: AppColors.console,
                borderRadius: BorderRadius.circular(14),
              ),
