mqtt_proto_code_t mqtt_proto_parse_config(const char *json, size_t len,
                                           const bool enabled[4], const uint8_t slave_ids[4],
                                           mqtt_proto_config_t *out)
{
    if (out == NULL) return MQTT_PROTO_INVALID_FIELDS;
    if (len > MQTT_PROTO_CONFIG_MAX) return MQTT_PROTO_PAYLOAD_TOO_LARGE;
    memset(out, 0, sizeof(*out));
    cJSON *root = NULL;
    mqtt_proto_code_t code = parse_common(json, len, &root, out->cmd_id);
    if (code != MQTT_PROTO_OK) return code;
    if (forbidden_config_field(root)) { cJSON_Delete(root); return MQTT_PROTO_FORBIDDEN; }

    const cJSON *type = get(root, "type");
    if (!cJSON_IsString(type)) code = MQTT_PROTO_INVALID_FIELDS;
    else if (strcmp(type->valuestring, "sensor") == 0) {
        out->kind = MQTT_PROTO_CONFIG_SENSOR;
        const cJSON *it = get(root, "interface_type");
        const cJSON *st = get(root, "sensor_type");
        const cJSON *name = get(root, "name");
        const cJSON *enabled_json = get(root, "enabled");
        int64_t index, slave = 0;
        double calib;
        const cJSON *index_json = get(root, "interface_index");
        const cJSON *calib_json = get(root, "calib_offset");
        if (!cJSON_IsString(it) || !cJSON_IsString(st) || !cJSON_IsString(name) ||
            !cJSON_IsBool(enabled_json) || !cJSON_IsNumber(index_json) || !cJSON_IsNumber(calib_json))
            code = MQTT_PROTO_INVALID_FIELDS;
        else if (!is_int(index_json, 0, 255, &index) ||
                 !is_number(calib_json, -100.0, 100.0, &calib) ||
                 !valid_utf8_name(name->valuestring)) code = MQTT_PROTO_INVALID_VALUE;
        else {
            if (strcmp(it->valuestring, "rs485") == 0) {
                out->interface_type = 0;
                const cJSON *slave_json = get(root, "slave_id");
                if (!cJSON_IsNumber(slave_json)) code = MQTT_PROTO_INVALID_FIELDS;
                else if (index >= 4 || !is_int(slave_json, 1, 247, &slave)) code = MQTT_PROTO_INVALID_VALUE;
                if (strcmp(st->valuestring, "sht40") == 0) out->sensor_type = 0;
                else if (strcmp(st->valuestring, "do") == 0) out->sensor_type = 1;
                else if (strcmp(st->valuestring, "ph") == 0) out->sensor_type = 2;
                else code = MQTT_PROTO_INVALID_VALUE;
                if (code == MQTT_PROTO_OK && cJSON_IsTrue(enabled_json) && enabled != NULL && slave_ids != NULL) {
                    for (size_t i = 0; i < 4; i++) if (i != (size_t)index && enabled[i] && slave_ids[i] == slave) code = MQTT_PROTO_CONFLICT;
                }
            } else if (strcmp(it->valuestring, "analog_4_20ma") == 0) {
                out->interface_type = 1;
                if (index != 0 || strcmp(st->valuestring, "analog_4_20ma") != 0) code = MQTT_PROTO_INVALID_VALUE;
                out->sensor_type = 3;
            } else code = MQTT_PROTO_INVALID_VALUE;
            if (code == MQTT_PROTO_OK) {
                out->interface_index = (uint8_t)index;
                out->slave_id = (uint8_t)slave;
                out->enabled = cJSON_IsTrue(enabled_json);
                out->calib_offset = (float)calib;
                memcpy(out->name, name->valuestring, strlen(name->valuestring) + 1U);
            }
        }
    } else if (strcmp(type->valuestring, "load_name") == 0) {
        out->kind = MQTT_PROTO_CONFIG_LOAD_NAME;
        const cJSON *name = get(root, "name");
        int64_t load;
        if (!cJSON_IsString(name) || !valid_utf8_name(name->valuestring) ||
            !is_int(get(root, "load_id"), 1, MQTT_PROTO_LOAD_MAX, &load)) code = MQTT_PROTO_INVALID_FIELDS;
        else {
            out->load_id = (uint8_t)load;
            memcpy(out->name, name->valuestring, strlen(name->valuestring) + 1U);
        }
    } else if (strcmp(type->valuestring, "load_control") == 0) {
        out->kind = MQTT_PROTO_CONFIG_LOAD_CONTROL;
        int64_t load, days;
        const cJSON *enabled_json = get(root, "enabled");
        const cJSON *schedule_json = get(root, "schedule_enabled");
        const cJSON *days_json = get(root, "days_mask");
        const cJSON *on_json = get(root, "on_time_utc");
        const cJSON *off_json = get(root, "off_time_utc");
        const cJSON *on_condition_enabled = get(root, "on_condition_enabled");
        const cJSON *off_condition_enabled = get(root, "off_condition_enabled");
        if (!cJSON_IsNumber(get(root, "load_id")) || !cJSON_IsBool(enabled_json) ||
            !cJSON_IsBool(schedule_json) || !cJSON_IsNumber(days_json) ||
            !cJSON_IsString(on_json) || !cJSON_IsString(off_json) ||
            !cJSON_IsBool(on_condition_enabled) || !cJSON_IsBool(off_condition_enabled) ||
            !cJSON_IsString(get(root, "on_sensor_id")) ||
            !cJSON_IsString(get(root, "on_operator")) ||
            !cJSON_IsNumber(get(root, "on_threshold")) ||
            !cJSON_IsString(get(root, "off_sensor_id")) ||
            !cJSON_IsString(get(root, "off_operator")) ||
            !cJSON_IsNumber(get(root, "off_threshold")))
            code = MQTT_PROTO_INVALID_FIELDS;
        else if (!is_int(get(root, "load_id"), 1, MQTT_PROTO_LOAD_MAX, &load) ||
                 !is_int(days_json, 0, 127, &days) ||
                 !parse_hhmm_utc(on_json, &out->on_minute_utc) ||
                 !parse_hhmm_utc(off_json, &out->off_minute_utc) ||
                 (cJSON_IsTrue(schedule_json) && days == 0) ||
                 (!cJSON_IsTrue(enabled_json) &&
                  (cJSON_IsTrue(schedule_json) || cJSON_IsTrue(on_condition_enabled) ||
                   cJSON_IsTrue(off_condition_enabled))) ||
                 !parse_sensor_condition(root, "on", &out->on_condition) ||
                 !parse_sensor_condition(root, "off", &out->off_condition) ||
                 (cJSON_IsTrue(schedule_json) &&
                  (cJSON_IsTrue(on_condition_enabled) || cJSON_IsTrue(off_condition_enabled))))
            code = MQTT_PROTO_INVALID_VALUE;
        else {
            out->load_id = (uint8_t)load;
            out->load_enabled = cJSON_IsTrue(enabled_json);
            out->schedule_enabled = cJSON_IsTrue(schedule_json);
            out->days_mask = (uint8_t)days;
        }
    } else if (strcmp(type->valuestring, "network") == 0) code = MQTT_PROTO_FORBIDDEN;
    else code = MQTT_PROTO_UNSUPPORTED_ACTION;

    cJSON_Delete(root);
    return code;
}

static cJSON *new_base(int version)
{
    cJSON *o = cJSON_CreateObject();
    if (o != NULL) cJSON_AddNumberToObject(o, "v", version);
    return o;
}

static void add_ts(cJSON *o, bool valid, int64_t ts)
{
    if (valid) cJSON_AddNumberToObject(o, "ts", (double)ts);
}

static int print_bounded(cJSON *o, char *out, size_t cap)
{
    if (o == NULL || out == NULL || cap == 0U) { cJSON_Delete(o); return -1; }
    char *text = cJSON_PrintUnformatted(o);
    cJSON_Delete(o);
    if (text == NULL) return -1;

