class ProvisionSuccessScreen extends StatefulWidget {
  const ProvisionSuccessScreen({super.key, required this.args});

  final ProvisionSuccessArgs args;

  @override
  State<ProvisionSuccessScreen> createState() => _ProvisionSuccessScreenState();
}

class _ProvisionSuccessScreenState extends State<ProvisionSuccessScreen> {
  @override
  void initState() {
    super.initState();
    // TODO: use the real values received from the ESP.
    WidgetsBinding.instance.addPostFrameCallback((_) {
      _registerDevice();
    });
  }

  Future<void> _registerDevice() async {
    try {
      await CrudApi.addDevice(
        userId: widget.args.userId,
        deviceMacAddress: widget.args.deviceId,
        defaultName: widget.args.deviceName,
        maxSensorCount: 4,
        maxLoadCount: 4,
        activeSensorCount: 0,
        internetMethod: 'ETH',
      );
      await MqttSessionManager.instance.startForUser(widget.args.userId);
      await MqttSessionManager.instance.addDevice(widget.args.deviceId);
    } catch (error) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Không thể đăng ký thiết bị MQTT: $error')),
      );
    }
  }

  @override
  Widget build(BuildContext context) {
    return ScreenScaffold(
      title: 'Hoàn tất',
      subtitle: 'Bước 3/3 · Chờ thiết bị kết nối',
      showBack: true,
      body: SingleChildScrollView(
        padding: const EdgeInsets.fromLTRB(16, 28, 16, 24),
        child: Column(
          children: [
            Container(
              width: 72,
              height: 72,
              decoration: BoxDecoration(
                shape: BoxShape.circle,
                border: Border.all(color: AppColors.primary, width: 2),
