              child: const Icon(
                Icons.check_rounded,
                color: AppColors.primary,
                size: 36,
              ),
            ),
            const SizedBox(height: 20),
            const Text(
              'Thiết lập cấu hình thành công',
              textAlign: TextAlign.center,
              style: AppTextStyles.heading,
            ),
            const SizedBox(height: 8),
            const Text(
              'Thiết bị đã lưu vào NVS và khởi động lại sau khoảng 2 giây.',
              textAlign: TextAlign.center,
              style: AppTextStyles.bodySecondary,
            ),
            const SizedBox(height: 22),
            const AppCard(
              child: Column(
                children: [
                  _StepRow(
                    icon: Icons.check_rounded,
                    label: 'Đã nhận cấu hình',
                    done: true,
                  ),
                  SizedBox(height: 12),
                  _StepRow(
                    icon: Icons.check_rounded,
                    label: 'Đã khởi động lại',
                    done: true,
                  ),
                  SizedBox(height: 12),
                  _StepRow(
                    icon: Icons.radio_button_unchecked,
                    label: 'Đang kết nối mạng',
                    done: false,
                  ),
                ],
              ),
            ),
            const SizedBox(height: 16),
            const GhostButton(label: 'Mở bảng điều khiển', onPressed: null),
            const SizedBox(height: 12),
            OutlineAppButton(
              label: 'Về danh sách thiết bị',
              onPressed: () {
                Navigator.of(
                  context,
                ).pushNamedAndRemoveUntil(AppRoutes.shell, (route) => false);
              },
            ),
          ],
        ),
      ),
    );
  }
}

class _StepRow extends StatelessWidget {
  const _StepRow({required this.icon, required this.label, required this.done});

  final IconData icon;
  final String label;
  final bool done;

  @override
  Widget build(BuildContext context) {
    return Row(
      children: [
        Icon(
          icon,
          size: 20,
          color: done ? AppColors.primary : AppColors.textSecondary,
        ),
        const SizedBox(width: 10),
        Text(label, style: AppTextStyles.body),
      ],
    );
  }

