int mqtt_proto_serialize_ack(const mqtt_proto_ack_t *ack, char *out, size_t cap)
{
    if (ack == NULL) return -1;
    cJSON *o = new_base(JSON_VERSION);
    if (ack->has_cmd_id) cJSON_AddStringToObject(o, "cmd_id", ack->cmd_id);
    else cJSON_AddNullToObject(o, "cmd_id");
    const char *kind = ack->kind == MQTT_PROTO_ACK_LOAD ? "load" :
                       ack->kind == MQTT_PROTO_ACK_CONFIG ? "config" :
                       ack->kind == MQTT_PROTO_ACK_QUERY ? "query" :
                       ack->kind == MQTT_PROTO_ACK_EMERGENCY ? "emergency" : "reject";
    cJSON_AddStringToObject(o, "kind", kind);
    cJSON_AddStringToObject(o, "result", ack->success ? "ok" : "error");
    cJSON_AddStringToObject(o, "code", mqtt_proto_code_name(ack->code));
    if (!ack->success && ack->reason[0]) cJSON_AddStringToObject(o, "reason", ack->reason);
    if (ack->kind == MQTT_PROTO_ACK_LOAD && ack->success) {
        cJSON *load = cJSON_CreateObject();
        cJSON_AddNumberToObject(load, "load_id", ack->load_id);
        cJSON_AddBoolToObject(load, "state", ack->state);
        cJSON_AddNumberToObject(load, "duration_min", ack->duration_min);
        if (ack->duration_sec != 0U) cJSON_AddNumberToObject(load, "duration_sec", ack->duration_sec);
        cJSON_AddNumberToObject(load, "remaining_s", ack->remaining_s);
        if (ack->cycle_mode == MQTT_PROTO_CYCLE_ON_THEN_OFF) {
            cJSON_AddStringToObject(load, "cycle_mode", cycle_mode_name(ack->cycle_mode));
            cJSON_AddNumberToObject(load, "on_delay_min", ack->on_delay_min);
            cJSON_AddNumberToObject(load, "duration", ack->duration);
        } else if (ack->cycle_mode == MQTT_PROTO_CYCLE_OFF_THEN_ON) {
            cJSON_AddStringToObject(load, "cycle_mode", cycle_mode_name(ack->cycle_mode));
            cJSON_AddNumberToObject(load, "off_delay_min", ack->off_delay_min);
            cJSON_AddNumberToObject(load, "duration", ack->duration);
        }
        cJSON_AddItemToObject(o, "load", load);
    } else if (ack->kind == MQTT_PROTO_ACK_CONFIG && ack->success) {
        cJSON *cfg = cJSON_CreateObject();
        if (ack->load_control_config) {
            cJSON_AddStringToObject(cfg, "type", "load_control");
            cJSON_AddNumberToObject(cfg, "load_id", ack->load_id);
        } else {
            cJSON_AddStringToObject(cfg, "interface_type", if_type_name(ack->interface_type));
            cJSON_AddNumberToObject(cfg, "interface_index", ack->interface_index);
        }
        cJSON_AddBoolToObject(cfg, "changed", ack->changed);
        cJSON_AddItemToObject(o, "config", cfg);
    } else if (ack->kind == MQTT_PROTO_ACK_EMERGENCY) {
        cJSON *emergency = cJSON_CreateObject();
        cJSON_AddBoolToObject(emergency, "active", ack->emergency_active);
        cJSON_AddBoolToObject(emergency, "changed", ack->emergency_changed);
        cJSON_AddNumberToObject(emergency, "loads_off", ack->loads_off);
        cJSON_AddItemToObject(o, "emergency", emergency);
    }
    cJSON_AddBoolToObject(o, "dup", ack->dup);
    add_ts(o, ack->has_ts, ack->ts_ms);
    return print_bounded(o, out, cap);
}

int mqtt_proto_serialize_telemetry(const mqtt_proto_telemetry_t *sample, char *out, size_t cap)
{
    if (sample == NULL || sample->sensor_count > MQTT_PROTO_SENSOR_MAX) return -1;
    cJSON *o = new_base(JSON_VERSION);
    cJSON_AddNumberToObject(o, "seq", sample->seq);
    cJSON_AddStringToObject(o, "boot_id", sample->boot_id ? sample->boot_id : "00000000");
    add_ts(o, sample->has_ts, sample->ts_ms);
    cJSON_AddNumberToObject(o, "uptime_ms", sample->uptime_ms);
    cJSON_AddBoolToObject(o, "buffered", sample->buffered);
    cJSON_AddStringToObject(o, "net_interface", sample->net_interface ? sample->net_interface : "NONE");
    cJSON *sensors = cJSON_CreateArray();
    cJSON_AddItemToObject(o, "sensors", sensors);
    for (size_t i=0;i<sample->sensor_count;i++) add_sensor(sensors,&sample->sensors[i],false);
    cJSON *errors = cJSON_CreateObject();
    cJSON_AddNumberToObject(errors,"code_mask",sample->error_mask);
    cJSON_AddItemToObject(o,"errors",errors);
    return print_bounded(o,out,cap);
}

