import 'package:flutter/material.dart';

import '../models/device_selection.dart';
import '../navigation/app_routes.dart';
import '../services/mqtt_session_manager.dart';
import '../theme/app_colors.dart';
import '../theme/app_text_styles.dart';
import '../widgets/app_buttons.dart';
import '../widgets/app_card.dart';
import '../widgets/screen_scaffold.dart';
import '../widgets/status_chip.dart';

class DeviceListScreen extends StatelessWidget {
  const DeviceListScreen({super.key, this.inShell = false});

  final bool inShell;

  @override
  Widget build(BuildContext context) {
    final manager = MqttSessionManager.instance;
    return ListenableBuilder(
      listenable: manager,
      builder: (context, _) {
        final devices = manager.deviceIds.toList()..sort();
        return ScreenScaffold(
          showMore: false,
          title: 'Danh sách thiết bị',
          subtitle: 'Thiết bị đã provision trên tài khoản này',
          showLogo: true,
          embedInTab: inShell,
          navIndex: inShell ? null : 0,
          onNavTap: inShell ? null : (i) => AppRoutes.openTab(context, i),
          body: SingleChildScrollView(
            padding: const EdgeInsets.fromLTRB(16, 16, 16, 24),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text('${devices.length} thiết bị', style: AppTextStyles.heading),
                const SizedBox(height: 16),
                PrimaryButton(
                  label: 'Thêm thiết bị',
                  icon: Icons.add,
                  onPressed: () {
                    Navigator.of(context, rootNavigator: true)
                        .pushNamed(AppRoutes.bleScan);
                  },
                ),
                const SizedBox(height: 16),
                if (devices.isEmpty)
                  const AppCard(
                    child: Text(
                      'Chưa có thiết bị được đăng ký. Hãy thêm thiết bị qua BLE provisioning.',
                      style: AppTextStyles.bodySecondary,
                    ),
                  ),
                for (var i = 0; i < devices.length; i++) ...[
                  if (i > 0) const SizedBox(height: 12),
                  _DeviceCard(
                    name: manager.deviceName(devices[i]),
                    network: devices[i],
                    detail: 'Chờ bản tin status từ ESP32',
                    chipLabel: manager.isConnected
                        ? 'Đang chờ status'
                        : 'MQTT chưa kết nối',
                    kind: StatusKind.degraded,
                    onView: () => Navigator.of(context).pushNamed(
                      AppRoutes.dashboard,
                      arguments: DeviceSelection(
                        deviceId: devices[i],
                        name: manager.deviceName(devices[i]),
                      ),
                    ),
                  ),
                ],
              ],
            ),
          ),
        );
      },
    );
  }
}

class _DeviceCard extends StatelessWidget {
  const _DeviceCard({
    required this.name,
    required this.network,
    required this.detail,
    required this.chipLabel,
    required this.kind,
    required this.onView,
  });

  final String name;
  final String network;
  final String detail;
  final String chipLabel;
  final StatusKind kind;
  final VoidCallback onView;

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      onTap: onView,
      child: AppCard(
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Expanded(
                child: Row(
                  children: [
                    Flexible(
                      child: Text(name, style: AppTextStyles.cardTitle),
                    ),
                    if (kind != StatusKind.online) ...[
                      const SizedBox(width: 6),
                      const Icon(
                        Icons.error_rounded,
                        size: 18,
                        color: AppColors.errorText,
                      ),
                    ],
                  ],
                ),
              ),
              StatusChip(label: chipLabel, kind: kind),
            ],
          ),
          const SizedBox(height: 8),
          const SizedBox(height: 10),
          Text(network, style: AppTextStyles.bodyMedium),
          const SizedBox(height: 4),
          Text(detail, style: AppTextStyles.bodySecondary),
