        'Weekly schedule and sensor conditions cannot both be enabled',
      );
    }
    if (!enabled && (scheduleEnabled || onConditionEnabled || offConditionEnabled)) {
      throw ArgumentError(
        'A disabled load cannot have an active schedule or sensor condition',
      );
    }
    return {
      'v': version,
      'cmd_id': cmdId,
      'type': 'load_control',
      'load_id': loadId,
      'enabled': enabled,
      'schedule_enabled': scheduleEnabled,
      'days_mask': daysMask,
      'on_time_utc': onTimeUtc,
      'off_time_utc': offTimeUtc,
      'on_condition_enabled': onConditionEnabled,
      'on_sensor_id': onSensorId,
      'on_operator': onOperator,
      'on_threshold': onThreshold,
      'off_condition_enabled': offConditionEnabled,
      'off_sensor_id': offSensorId,
      'off_operator': offOperator,
      'off_threshold': offThreshold,
    };
  }

  static void _validateCommand(String cmdId) {
    if (!_cmdIdPattern.hasMatch(cmdId)) {
      throw ArgumentError.value(cmdId, 'cmdId');
    }
  }

  static void _validateLoadId(int loadId) {
    if (loadId < 1 || loadId > 4) {
      throw ArgumentError.value(loadId, 'loadId');
    }
  }

  static void _validateName(String name) {
    final encodedLength = utf8.encode(name).length;
    if (name.isEmpty ||
        encodedLength > 31 ||
        name.trim() != name ||
        name.codeUnits.any((unit) => unit < 0x20 || unit == 0x7f)) {
      throw ArgumentError.value(name, 'name');
    }
  }

  static void _validateTime(String value, String name) {
    final match = RegExp(r'^([01]\d|2[0-3]):[0-5]\d$').hasMatch(value);
    if (!match) throw ArgumentError.value(value, name);
  }

  static void _validateCondition(
    String sensorId,
    String operator,
    double threshold,
    String prefix,
  ) {
    if (!_sensorIdPattern.hasMatch(sensorId) ||
        !_operators.contains(operator) ||
        !threshold.isFinite ||
        threshold < -1000000 ||
        threshold > 1000000) {
      throw ArgumentError('Invalid $prefix sensor condition');
    }
  }
}

