import 'package:flutter/material.dart';

import '../models/device_selection.dart';
import '../navigation/app_routes.dart';
import '../services/crud_api.dart';
import '../services/device_api.dart';
import '../services/mqtt_session_manager.dart';
import '../protocol/mqtt_payloads.dart';
import '../state/load_controller.dart';
import '../state/sensors_state.dart';
import '../theme/app_colors.dart';
import '../theme/app_text_styles.dart';
import '../widgets/app_buttons.dart';
import '../widgets/app_card.dart';
import '../widgets/app_more_menu.dart';
import '../widgets/rename_dialog.dart';
import '../widgets/screen_scaffold.dart';
import '../widgets/status_chip.dart';

class DashboardScreen extends StatefulWidget {
  const DashboardScreen({
    super.key,
    required this.device,
    this.inShell = true,
  });

  final DeviceSelection device;
  final bool inShell;

  @override
  State<DashboardScreen> createState() => _DashboardScreenState();
}

class _DashboardScreenState extends State<DashboardScreen> {
  int _tab = 0;
  late String _name = widget.device.name;

  Future<void> _rename() async {
    final name = await showDialog<String>(
      context: context,
      builder: (_) => RenameDialog(
        title: 'Đổi tên thiết bị',
        hint: 'Tên thiết bị',
        initial: _name,
      ),
    );
    final v = name?.trim();
    if (v == null || v.isEmpty || !mounted) return;
    setState(() => _name = v);
    await CrudApi.renameDevice(widget.device.deviceId, v);
  }

  Future<void> _emergencyStop() async {
    final messenger = ScaffoldMessenger.of(context);
    try {
      final ack = await MqttSessionManager.instance.publishCommandAndWaitForAck(
        widget.device.deviceId,
        MqttPayloads.emergencyStop(cmdId: MqttPayloads.newCommandId()),
      );
      if (!mounted) return;
      if (!ack.isSuccess) {
        messenger.showSnackBar(
          SnackBar(content: Text('Dừng khẩn cấp bị từ chối: ${ack.code}')),
        );
        return;
      }
      for (final load in LoadController.loads) {
        load.cancelDelay();
        load.setOn(false);
      }
      sensorsRunning.value = false;
      messenger.showSnackBar(
        const SnackBar(content: Text('ESP32 đã xác nhận dừng khẩn cấp')),
      );
    } catch (error) {
      if (!mounted) return;
      messenger.showSnackBar(
        SnackBar(content: Text('Không gửi/xác nhận được dừng khẩn cấp: $error')),
      );
    }
  }

  Future<void> _confirmDelete() async {
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        backgroundColor: AppColors.surface,
        surfaceTintColor: Colors.transparent,
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(18)),
        title: const Text('Xóa thiết bị', style: AppTextStyles.sectionTitle),
        content: Text(
          'Bạn có chắc chắn muốn xóa thiết bị $_name?',
          style: AppTextStyles.bodySecondary,
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(ctx).pop(false),
            child: Text(
              'Hủy',
              style: AppTextStyles.link.copyWith(
                color: AppColors.textSecondary,
              ),
            ),
          ),
          TextButton(
            onPressed: () => Navigator.of(ctx).pop(true),
            child: Text(
              'Đồng ý',
              style: AppTextStyles.link.copyWith(color: AppColors.errorText),
            ),
          ),
        ],
      ),
    );
    if (confirmed != true || !mounted) return;
    await DeviceApi.deleteDevice('ao_nuoi_a1');
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(content: Text('Đã gửi yêu cầu xóa thiết bị')),
    );
  }

  @override
  Widget build(BuildContext context) {
    return ScreenScaffold(
      title: 'Bảng điều khiển',
      subtitle: '$_name · Vận hành bình thường',
      showBack: true,
      embedInTab: widget.inShell,
      navIndex: widget.inShell ? null : 0,
      onNavTap: widget.inShell ? null : (i) => AppRoutes.openTab(context, i),
      headerTrailing: AppMoreMenu<String>(
        onSelected: (_) => _confirmDelete(),
        itemBuilder: (_) => const [
          PopupMenuItem(
            value: 'delete',
            child: Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                Icon(
                  Icons.delete_outline_rounded,
                  size: 20,
                  color: AppColors.errorText,
                ),
                SizedBox(width: 10),
                Text(
                  'Xóa thiết bị',
                  style: TextStyle(
                    fontSize: 14,
                    fontWeight: FontWeight.w500,
                    color: AppColors.errorText,
                  ),
                ),
              ],
            ),
          ),
        ],
      ),
      body: Column(
        children: [
          Padding(
            padding: const EdgeInsets.fromLTRB(16, 16, 16, 0),
            child: _DeviceSummaryCard(
              name: _name,
              onRename: _rename,
              onEmergencyStop: _emergencyStop,
            ),
          ),
          Padding(
            padding: const EdgeInsets.fromLTRB(16, 14, 16, 14),
            child: Row(
              children: [
                _SegChip(
                  label: 'Cảm biến',
                  selected: _tab == 0,
                  onTap: () => setState(() => _tab = 0),
                ),
                const SizedBox(width: 8),
                _SegChip(
                  label: 'Tải',
                  selected: _tab == 1,
                  onTap: () => setState(() => _tab = 1),
                ),
              ],
            ),
          ),
          Expanded(
            child: SingleChildScrollView(
              padding: const EdgeInsets.fromLTRB(16, 0, 16, 24),
              child: _tab == 0
                  ? const _SensorsTab()
                  : _LoadsTab(device: widget.device),
            ),
          ),
        ],
      ),
    );
  }
}

class _SegChip extends StatelessWidget {
  const _SegChip({
    required this.label,
    required this.selected,
    required this.onTap,
  });

  final String label;
  final bool selected;
  final VoidCallback onTap;

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      onTap: onTap,
      child: Container(
        height: 38,
        padding: const EdgeInsets.symmetric(horizontal: 18),
        alignment: Alignment.center,
        decoration: BoxDecoration(
          color: selected ? AppColors.primary : AppColors.surface,
          borderRadius: BorderRadius.circular(12),
          border: Border.all(
            color: selected ? AppColors.primary : AppColors.border,
          ),
        ),
        child: Text(
          label,
          style: AppTextStyles.bodyMedium.copyWith(
            color: selected ? AppColors.textOnPrimary : AppColors.textSecondary,
            fontWeight: FontWeight.w600,
          ),
        ),
      ),
    );
  }
}

class _SensorsTab extends StatelessWidget {
  const _SensorsTab();

  @override
  Widget build(BuildContext context) {
    return ValueListenableBuilder<bool>(
      valueListenable: sensorsRunning,
      builder: (context, running, _) =>
          running ? _buildRunning(context) : _buildStopped(),
    );
  }

  Widget _buildStopped() {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        const Text('Cảm biến hiện tại', style: AppTextStyles.sectionTitle),
        const SizedBox(height: 12),
        const AppCard(
          color: AppColors.errorBg,
          borderColor: AppColors.errorSoft,
          child: Text(
            'Cảm biến đã TẮT do dừng khẩn cấp.',
            style: AppTextStyles.bodyMedium,
          ),
        ),
        const SizedBox(height: 14),
        OutlineAppButton(
          label: 'Bật lại cảm biến',
          icon: Icons.power_settings_new_rounded,
          onPressed: () => sensorsRunning.value = true,
        ),
      ],
    );
  }

  Widget _buildRunning(BuildContext context) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        const _AlertCard(message: 'Lỗi mất kết nối với cảm biến Nhiệt độ'),
        const SizedBox(height: 20),
        const Text('Cảm biến hiện tại', style: AppTextStyles.sectionTitle),
        const SizedBox(height: 12),
        AppCard(
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              const Text(
                'SHT40 · Temp_Humid_Room',
                style: AppTextStyles.caption,
              ),
              const SizedBox(height: 8),
              const Row(
                children: [
                  Expanded(
                    child: _Metric(
                      value: '29.1',
                      unit: '°C',
                      caption: 'Nhiệt độ phòng',
                    ),
                  ),
                  Expanded(
                    child: _Metric(
                      value: '68.4',
                      unit: '%',
                      caption: 'Độ ẩm phòng',
                    ),
                  ),
                ],
              ),
              const SizedBox(height: 10),
              const Text(
                'Hết thời gian chờ Modbus. Kiểm tra cảm biến và đường truyền RS485.',
                style: AppTextStyles.caption,
              ),
              const SizedBox(height: 10),
              const StatusChip(label: 'Lỗi', kind: StatusKind.error),
            ],
          ),
        ),
        const SizedBox(height: 12),
        const Row(
          children: [
            Expanded(
              child: AppCard(
                child: _SmallSensor(
                  title: 'Oxy hòa tan · DO',
                  value: '6.82',
                  unit: 'mg/L',
                  id: 'DO_Tank_1',
                ),
              ),
            ),
            SizedBox(width: 10),
            Expanded(
              child: AppCard(
                child: _SmallSensor(
                  title: 'Độ pH',
                  value: '7.15',
                  unit: 'pH',
                  id: 'pH_Tank_A1',
                ),
              ),
            ),
          ],
        ),
        const SizedBox(height: 14),
        OutlineAppButton(
          label: 'Tùy chỉnh',
          icon: Icons.tune_rounded,
          onPressed: () {
            Navigator.of(context).pushNamed(
              AppRoutes.sensorCapacity,
              arguments: widget.device,
            );
          },
        ),
      ],
    );
  }
}

class _DeviceSummaryCard extends StatelessWidget {
  const _DeviceSummaryCard({
    required this.name,
    required this.onRename,
    required this.onEmergencyStop,
  });

  final String name;
  final VoidCallback onRename;
  final VoidCallback onEmergencyStop;

  @override
  Widget build(BuildContext context) {
    return AppCard(
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Flexible(child: Text(name, style: AppTextStyles.heading)),
              IconButton(
                onPressed: onRename,
                tooltip: 'Đổi tên thiết bị',
                visualDensity: VisualDensity.compact,
                icon: const Icon(
                  Icons.edit_rounded,
                  size: 18,
                  color: AppColors.primary,
                ),
              ),
              const Spacer(),
              SizedBox(
                height: 40,
                child: ElevatedButton.icon(
                  onPressed: onEmergencyStop,
                  icon: const Icon(Icons.stop_circle_rounded),
                  label: const Text('Dừng khẩn cấp'),
                  style: ElevatedButton.styleFrom(
                    backgroundColor: AppColors.errorText,
                    foregroundColor: AppColors.textOnPrimary,
                    elevation: 0,
                    padding: const EdgeInsets.symmetric(horizontal: 12),
                    textStyle: AppTextStyles.button.copyWith(
                      fontWeight: FontWeight.w700,
                    ),
                    shape: RoundedRectangleBorder(
                      borderRadius: BorderRadius.circular(12),
                    ),
                  ),
                ),
              ),
            ],
          ),
          const SizedBox(height: 10),
          const Row(
            crossAxisAlignment: CrossAxisAlignment.center,
            children: [
              StatusChip(label: 'Trực tuyến', kind: StatusKind.online),
              Spacer(),
              Text('ETH · đã kết nối', style: AppTextStyles.bodyMedium),
            ],
          ),
        ],
      ),
    );
  }
}
class _AlertCard extends StatelessWidget {
  const _AlertCard({required this.message});

  final String message;

  @override
  Widget build(BuildContext context) {
    return AppCard(
      color: AppColors.errorBg,
      borderColor: AppColors.errorSoft,
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            'Có cảnh báo',
            style: AppTextStyles.bodyMedium.copyWith(color: AppColors.errorText),
          ),
          const SizedBox(height: 6),
          Text(
            message,
            style: AppTextStyles.body.copyWith(color: AppColors.errorText),
          ),
        ],
      ),
    );
  }
}

class _LoadsTab extends StatelessWidget {
  const _LoadsTab();

  @override
  Widget build(BuildContext context) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        const _AlertCard(
          message: 'Load 4 không phản hồi lệnh điều khiển gần nhất',
        ),
        const SizedBox(height: 20),
        Text(
          'Tải hiện tại · ${LoadController.loads.length} tải',
          style: AppTextStyles.sectionTitle,
        ),
        const SizedBox(height: 12),
        for (final load in LoadController.loads) ...[
          _LoadCard(load: load),
          if (load != LoadController.loads.last) const SizedBox(height: 12),
        ],
      ],
    );
  }
}

class _LoadCard extends StatelessWidget {
  const _LoadCard({required this.load});

  final LoadController load;

  @override
  Widget build(BuildContext context) {
    return ListenableBuilder(
      listenable: load,
      builder: (context, _) {
        final on = load.isOn && load.enabled;
        return AppCard(
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Row(
                children: [
                  Expanded(
                    child: Text(load.title, style: AppTextStyles.cardTitle),
                  ),
                  Switch(
                    value: load.isOn,
                    onChanged: load.enabled ? load.setOn : null,
                  ),
                ],
              ),
              Text(load.tag, style: AppTextStyles.monoCaption),
              const SizedBox(height: 14),
              Row(
                crossAxisAlignment: CrossAxisAlignment.end,
                children: [
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          !load.enabled
                              ? 'Không cho phép'
                              : (on ? 'Đang bật' : 'Đang tắt'),
                          style: AppTextStyles.metric,
                        ),
                        const SizedBox(height: 4),
                        Text(
                          'Trạng thái thực tế · Đã xác nhận',
                          style: AppTextStyles.bodySecondary.copyWith(
                            color: AppColors.primary,
                          ),
                        ),
                      ],
                    ),
                  ),
                  if (load.delayActive)
                    Column(
                      crossAxisAlignment: CrossAxisAlignment.end,
                      children: [
                        Text(
                          load.delayCountdown,
                          style: AppTextStyles.countdown,
                        ),
                        const SizedBox(height: 4),
                        Text(
                          load.delayTargetOn
                              ? 'còn lại trước tự bật'
                              : 'còn lại trước tự tắt',
                          style: AppTextStyles.caption,
                        ),
                      ],
                    ),
                ],
              ),
              const SizedBox(height: 10),
              const Text(
                'Ảnh chụp mẫu · Lệnh bật 60 giây trước đó đã nhận ACK.',
                style: AppTextStyles.caption,
              ),
              const SizedBox(height: 12),
              const Divider(height: 1, color: AppColors.divider),
              InkWell(
                onTap: () {
                  Navigator.of(context)
                      .pushNamed(AppRoutes.loadControl, arguments: load);
                },
                child: Padding(
                  padding: const EdgeInsets.only(top: 14, bottom: 2),
                  child: Row(
                    children: [
                      Expanded(
                        child: Text(
                          'Điều khiển & cấu hình Load ${load.id}',
                          style: AppTextStyles.link,
                        ),
                      ),
                      const Icon(
                        Icons.arrow_forward_rounded,
                        color: AppColors.primary,
                        size: 22,
                      ),
                    ],
                  ),
                ),
              ),
            ],
          ),
        );
      },
    );
  }
}

class _Metric extends StatelessWidget {
  const _Metric({
    required this.value,
    required this.unit,
    required this.caption,
  });

  final String value;
  final String unit;
  final String caption;

  @override
  Widget build(BuildContext context) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Row(
          crossAxisAlignment: CrossAxisAlignment.end,
          children: [
            Text(value, style: AppTextStyles.metric),
            const SizedBox(width: 6),
            Padding(
              padding: const EdgeInsets.only(bottom: 4),
              child: Text(unit, style: AppTextStyles.unit),
            ),
          ],
        ),
        const SizedBox(height: 4),
        Text(caption, style: AppTextStyles.caption),
      ],
    );
  }
}

class _SmallSensor extends StatelessWidget {
  const _SmallSensor({
    required this.title,
    required this.value,
    required this.unit,
    required this.id,
  });

  final String title;
  final String value;
  final String unit;
  final String id;

  @override
  Widget build(BuildContext context) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Text(title, style: AppTextStyles.caption),
        const SizedBox(height: 8),
        Row(
          crossAxisAlignment: CrossAxisAlignment.end,
          children: [
            Text(value, style: AppTextStyles.metric),
            const SizedBox(width: 4),
            Padding(
              padding: const EdgeInsets.only(bottom: 4),
              child: Text(unit, style: AppTextStyles.unit),
            ),
          ],
        ),
        const SizedBox(height: 6),
        Text(id, style: AppTextStyles.caption),
        const SizedBox(height: 8),
        const StatusChip(label: 'Hợp lệ', kind: StatusKind.valid),
      ],
    );
  }
}

