        cmdId: MqttPayloads.newCommandId(),
        interfaceType: selection.interfaceType,
        interfaceIndex: selection.interfaceIndex,
        sensorType: _sensorType,
        name: _name.text.trim(),
        enabled: _enabled,
        calibrationOffset:
            double.tryParse(_offset.text.trim()) ??
            (throw const FormatException('Giá trị bù phải là số hữu hạn.')),
        slaveId: selection.interfaceType == 'rs485'
            ? int.tryParse(_slave.text.trim())
            : null,
      );
      final ack = await MqttSessionManager.instance
          .publishConfigAndWaitForAck(selection.device.deviceId, payload);
      if (!mounted) return false;
      if (!ack.isSuccess) {
        throw StateError('ESP32 từ chối cấu hình: ${ack.code}');
      }
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('ESP32 đã xác nhận cấu hình cảm biến')),
      );
      if (closeOnSuccess) Navigator.of(context).pop(true);
      return true;
    } catch (error) {
      if (!mounted) return false;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Không lưu được cấu hình cảm biến: $error')),
      );
      return false;
    } finally {
      if (mounted) setState(() => _sending = false);
    }
  }

  Future<void> _setEnabled(bool enabled) async {
    final previous = _enabled;
    setState(() => _enabled = enabled);
    final saved = await _save();
    if (!mounted) return;
    if (!saved) setState(() => _enabled = previous);
  }

