      subtitle:
          '${selection.device.name} · ${selection.interfaceType} #${selection.interfaceIndex}',
      showBack: true,
      embedInTab: widget.inShell,
      navIndex: widget.inShell ? null : 0,
      onNavTap: widget.inShell ? null : (i) => AppRoutes.openTab(context, i),
      body: SingleChildScrollView(
        padding: const EdgeInsets.fromLTRB(16, 16, 16, 24),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            AppCard(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    'Cổng ${selection.interfaceIndex + 1} · ${selection.interfaceType}',
                    style: AppTextStyles.bodyMedium,
                  ),
                  const SizedBox(height: 6),
                  Text(
                    'Device ID: ${selection.device.deviceId}',
                    style: AppTextStyles.mono,
                  ),
                  const SizedBox(height: 14),
                  SwitchListTile(
                    contentPadding: EdgeInsets.zero,
                    title: const Text('Cho phép cảm biến'),
                    value: _enabled,
                    onChanged: _sending ? null : _setEnabled,
                  ),
                ],
              ),
            ),
            const SizedBox(height: 18),
            Text(
              isRs485 ? 'Loại cảm biến RS485' : 'Loại cảm biến',
              style: AppTextStyles.label,
            ),
            const SizedBox(height: 10),
            if (isRs485)
              Wrap(
                spacing: 8,
                children: [
                  for (final type in const ['sht40', 'do', 'ph'])
                    ChoiceChip(
                      label: Text(type.toUpperCase()),
                      selected: _sensorType == type,
                      onSelected: _sending
                          ? null
                          : (_) => setState(() => _sensorType = type),
                    ),
                ],
              )
            else
              const AppCard(
                child: Text(
                  'Analog 4–20 mA',
                  style: AppTextStyles.bodyMedium,
                ),
              ),
            const SizedBox(height: 16),
            AppTextField(
              label: 'Tên cảm biến · name',
              controller: _name,
              helper: 'Tối đa 31 byte UTF-8 theo contract firmware.',
            ),
            if (isRs485) ...[
              const SizedBox(height: 16),
              AppTextField(
                label: 'Địa chỉ Modbus · slave_id',
                controller: _slave,
                keyboardType: TextInputType.number,
                helper: 'Số nguyên từ 1 đến 247.',
              ),
            ],
            const SizedBox(height: 16),
            AppTextField(
              label: 'Bù hiệu chuẩn · calib_offset',
              controller: _offset,
              keyboardType: const TextInputType.numberWithOptions(
                decimal: true,
                signed: true,
              ),
              helper: 'Giới hạn firmware: -100 đến 100.',
            ),
            const SizedBox(height: 20),
            PrimaryButton(
              label: _sending ? 'Đang chờ ACK từ ESP32...' : 'Gửi cấu hình',
              icon: Icons.send_rounded,
              onPressed: _sending ? null : () => _save(closeOnSuccess: true),
            ),
          ],
        ),
      ),
    );
  }
}

