}

class _LoadsTab extends StatelessWidget {
  const _LoadsTab({required this.device});

  final DeviceSelection device;

  @override
  Widget build(BuildContext context) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        const _AlertCard(
          message: 'Load 4 không phản hồi lệnh điều khiển gần nhất',
        ),
        const SizedBox(height: 20),
        Text(
          'Tải hiện tại · ${LoadController.loads.length} tải',
          style: AppTextStyles.sectionTitle,
        ),
        const SizedBox(height: 12),
        for (final load in LoadController.loads) ...[
          _LoadCard(load: load, device: device),
          if (load != LoadController.loads.last) const SizedBox(height: 12),
        ],
      ],
    );
  }
}

class _LoadCard extends StatelessWidget {
  const _LoadCard({required this.load, required this.device});

  final LoadController load;
  final DeviceSelection device;

  Future<void> _setState(BuildContext context, bool state) async {
    try {
      final ack = await MqttSessionManager.instance.publishCommandAndWaitForAck(
        device.deviceId,
        MqttPayloads.setState(
          cmdId: MqttPayloads.newCommandId(),
          loadId: load.id,
          state: state,
        ),
      );
      if (!context.mounted) return;
      if (!ack.isSuccess) {
        throw StateError('ESP32 từ chối lệnh: ${ack.code}');
      }
      load.setOn(state);
    } catch (error) {
      if (!context.mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Không điều khiển được tải: $error')),
      );
    }
  }

  @override
  Widget build(BuildContext context) {
    return ListenableBuilder(
      listenable: load,
      builder: (context, _) {
        final on = load.isOn && load.enabled;
        return AppCard(
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Row(
                children: [
                  Expanded(
                    child: Text(load.title, style: AppTextStyles.cardTitle),
                  ),
                  Switch(
                    value: load.isOn,
                    onChanged: load.enabled
                        ? (value) => _setState(context, value)
                        : null,
                  ),
                ],
              ),
              Text(load.tag, style: AppTextStyles.monoCaption),
              const SizedBox(height: 14),
              Row(
                crossAxisAlignment: CrossAxisAlignment.end,
                children: [
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          !load.enabled
                              ? 'Không cho phép'
                              : (on ? 'Đang bật' : 'Đang tắt'),
                          style: AppTextStyles.metric,
                        ),
                        const SizedBox(height: 4),
                        Text(
                          'Trạng thái thực tế · Đã xác nhận',
                          style: AppTextStyles.bodySecondary.copyWith(
                            color: AppColors.primary,
                          ),
                        ),
                      ],
                    ),
                  ),
                  if (load.delayActive)
                    Column(
                      crossAxisAlignment: CrossAxisAlignment.end,
                      children: [
                        Text(
                          load.delayCountdown,
                          style: AppTextStyles.countdown,
                        ),
                        const SizedBox(height: 4),
                        Text(
                          load.delayTargetOn
                              ? 'còn lại trước tự bật'
                              : 'còn lại trước tự tắt',
                          style: AppTextStyles.caption,
                        ),
                      ],
                    ),
                ],
              ),
              const SizedBox(height: 10),
              const Text(
                'Ảnh chụp mẫu · Lệnh bật 60 giây trước đó đã nhận ACK.',
                style: AppTextStyles.caption,
              ),
              const SizedBox(height: 12),
              const Divider(height: 1, color: AppColors.divider),
              InkWell(
                onTap: () {
                  Navigator.of(context)
                      .pushNamed(
                        AppRoutes.loadControl,
                        arguments: LoadControlArgs(device: device, load: load),
                      );
                },
                child: Padding(
                  padding: const EdgeInsets.only(top: 14, bottom: 2),
                  child: Row(
                    children: [
                      Expanded(
                        child: Text(
                          'Điều khiển & cấu hình Load ${load.id}',
                          style: AppTextStyles.link,
                        ),
                      ),
                      const Icon(
                        Icons.arrow_forward_rounded,
                        color: AppColors.primary,
                        size: 22,
                      ),
                    ],
                  ),
                ),
              ),
            ],
          ),
        );
      },
    );
  }
}

class _Metric extends StatelessWidget {
  const _Metric({
    required this.value,
    required this.unit,
    required this.caption,
  });

  final String value;
  final String unit;
  final String caption;

  @override
  Widget build(BuildContext context) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Row(
          crossAxisAlignment: CrossAxisAlignment.end,
          children: [
            Text(value, style: AppTextStyles.metric),
            const SizedBox(width: 6),
            Padding(
              padding: const EdgeInsets.only(bottom: 4),
              child: Text(unit, style: AppTextStyles.unit),
            ),
          ],
        ),
        const SizedBox(height: 4),
        Text(caption, style: AppTextStyles.caption),
      ],
    );
  }
}

class _SmallSensor extends StatelessWidget {
  const _SmallSensor({
    required this.title,
    required this.value,
    required this.unit,
    required this.id,
  });

  final String title;
  final String value;
  final String unit;
  final String id;

  @override
  Widget build(BuildContext context) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Text(title, style: AppTextStyles.caption),
        const SizedBox(height: 8),
        Row(
          crossAxisAlignment: CrossAxisAlignment.end,
          children: [
            Text(value, style: AppTextStyles.metric),
            const SizedBox(width: 4),
            Padding(
              padding: const EdgeInsets.only(bottom: 4),
              child: Text(unit, style: AppTextStyles.unit),
            ),
          ],
        ),
        const SizedBox(height: 6),
        Text(id, style: AppTextStyles.caption),
        const SizedBox(height: 8),
        const StatusChip(label: 'Hợp lệ', kind: StatusKind.valid),
      ],
    );
  }
}

