import 'package:flutter/material.dart';

import '../models/device_selection.dart';
import '../navigation/app_routes.dart';
import '../protocol/mqtt_payloads.dart';
import '../services/mqtt_session_manager.dart';
import '../theme/app_colors.dart';
import '../theme/app_text_styles.dart';
import '../widgets/app_buttons.dart';
import '../widgets/app_card.dart';
import '../widgets/app_text_field.dart';
import '../widgets/screen_scaffold.dart';

class SensorConfigScreen extends StatefulWidget {
  const SensorConfigScreen({
    super.key,
    required this.selection,
    this.inShell = true,
  });

  final SensorConfigSelection selection;
  final bool inShell;

  @override
  State<SensorConfigScreen> createState() => _SensorConfigScreenState();
}

class _SensorConfigScreenState extends State<SensorConfigScreen> {
  late String _sensorType = widget.selection.sensorType;
  late bool _enabled = widget.selection.enabled;
  late final _slave = TextEditingController(
    text: widget.selection.slaveId?.toString() ?? '1',
  );
  late final _name = TextEditingController(text: widget.selection.name);
  late final _offset = TextEditingController(
    text: widget.selection.calibrationOffset.toString(),
  );
  bool _sending = false;

  @override
  void dispose() {
    _slave.dispose();
    _name.dispose();
    _offset.dispose();
    super.dispose();
  }

  Future<bool> _save({bool closeOnSuccess = false}) async {
    if (_sending) return false;
    setState(() => _sending = true);
    try {
      final selection = widget.selection;
      final payload = MqttPayloads.setSensorConfig(
        cmdId: MqttPayloads.newCommandId(),
        interfaceType: selection.interfaceType,
        interfaceIndex: selection.interfaceIndex,
        sensorType: _sensorType,
        name: _name.text.trim(),
        enabled: _enabled,
        calibrationOffset:
            double.tryParse(_offset.text.trim()) ??
            (throw const FormatException('Giá trị bù phải là số hữu hạn.')),
        slaveId: selection.interfaceType == 'rs485'
            ? int.tryParse(_slave.text.trim())
            : null,
      );
      final ack = await MqttSessionManager.instance
          .publishConfigAndWaitForAck(selection.device.deviceId, payload);
      if (!mounted) return false;
      if (!ack.isSuccess) {
        throw StateError('ESP32 từ chối cấu hình: ${ack.code}');
      }
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('ESP32 đã xác nhận cấu hình cảm biến')),
      );
      if (closeOnSuccess) {
        Navigator.of(context).pop(
          SensorConfigSelection(
            device: selection.device,
            interfaceType: selection.interfaceType,
            interfaceIndex: selection.interfaceIndex,
            sensorType: _sensorType,
            name: _name.text.trim(),
            isNew: selection.isNew,
            slaveId: selection.interfaceType == 'rs485'
                ? int.parse(_slave.text.trim())
                : null,
            enabled: _enabled,
            calibrationOffset: double.parse(_offset.text.trim()),
          ),
        );
      }
      return true;
    } catch (error) {
      if (!mounted) return false;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Không lưu được cấu hình cảm biến: $error')),
      );
      return false;
    } finally {
      if (mounted) setState(() => _sending = false);
    }
  }

  Future<void> _setEnabled(bool enabled) async {
    final previous = _enabled;
    setState(() => _enabled = enabled);
    final saved = await _save();
    if (!mounted) return;
    if (!saved) setState(() => _enabled = previous);
  }

  @override
  Widget build(BuildContext context) {
    final selection = widget.selection;
    final isRs485 = selection.interfaceType == 'rs485';
    return ScreenScaffold(
      title: 'Cấu hình cảm biến',
      subtitle:
          '${selection.device.name} · ${selection.interfaceType} #${selection.interfaceIndex}',
      showBack: true,
      embedInTab: widget.inShell,
      navIndex: widget.inShell ? null : 0,
      onNavTap: widget.inShell ? null : (i) => AppRoutes.openTab(context, i),
      body: SingleChildScrollView(
        padding: const EdgeInsets.fromLTRB(16, 16, 16, 24),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            AppCard(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    'Cổng ${selection.interfaceIndex + 1} · ${selection.interfaceType}',
                    style: AppTextStyles.bodyMedium,
                  ),
                  const SizedBox(height: 6),
                  Text(
                    'Device ID: ${selection.device.deviceId}',
                    style: AppTextStyles.mono,
                  ),
                  const SizedBox(height: 14),
                  SwitchListTile(
                    contentPadding: EdgeInsets.zero,
                    title: const Text('Cho phép cảm biến'),
                    value: _enabled,
                    onChanged: _sending ? null : _setEnabled,
                  ),
                ],
              ),
            ),
            const SizedBox(height: 18),
            Text(
              isRs485 ? 'Loại cảm biến RS485' : 'Loại cảm biến',
              style: AppTextStyles.label,
            ),
            const SizedBox(height: 10),
            if (isRs485)
              Wrap(
                spacing: 8,
                children: [
                  for (final type in const ['sht40', 'do', 'ph'])
                    ChoiceChip(
                      label: Text(type.toUpperCase()),
                      selected: _sensorType == type,
                      onSelected: _sending
                          ? null
                          : (_) => setState(() => _sensorType = type),
                    ),
                ],
              )
            else
              const AppCard(
                child: Text(
                  'Analog 4–20 mA',
                  style: AppTextStyles.bodyMedium,
                ),
              ),
            const SizedBox(height: 16),
            AppTextField(
              label: 'Tên cảm biến · name',
              controller: _name,
              helper: 'Tối đa 31 byte UTF-8 theo contract firmware.',
            ),
            if (isRs485) ...[
              const SizedBox(height: 16),
              AppTextField(
                label: 'Địa chỉ Modbus · slave_id',
                controller: _slave,
                keyboardType: TextInputType.number,
                helper: 'Số nguyên từ 1 đến 247.',
              ),
            ],
            const SizedBox(height: 16),
            AppTextField(
              label: 'Bù hiệu chuẩn · calib_offset',
              controller: _offset,
              keyboardType: const TextInputType.numberWithOptions(
                decimal: true,
                signed: true,
              ),
              helper: 'Giới hạn firmware: -100 đến 100.',
            ),
            const SizedBox(height: 20),
            PrimaryButton(
              label: _sending ? 'Đang chờ ACK từ ESP32...' : 'Gửi cấu hình',
              icon: Icons.send_rounded,
              onPressed: _sending ? null : () => _save(closeOnSuccess: true),
            ),
          ],
        ),
      ),
    );
  }
}

