import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:flutter_app/services/crud_api.dart';

import 'package:flutter_app/screens/load_control_screen.dart';
import 'package:flutter_app/screens/login_screen.dart';
import 'package:flutter_app/screens/sensor_capacity_screen.dart';
import 'package:flutter_app/screens/sensor_config_screen.dart';
import 'package:flutter_app/screens/settings_screen.dart';
import 'package:flutter_app/state/developer_access_controller.dart';
import 'package:flutter_app/state/load_controller.dart';
import 'package:flutter_app/theme/app_theme.dart';

Widget _wrap(Widget child) => MaterialApp(theme: AppTheme.light, home: child);

void main() {
  setUpAll(() => EspAck.delay = Duration.zero);

  setUp(() {
    DeveloperAccessController.instance.setAccess(true);
    LoadController.instance
      ..setEnabled(true)
      ..setOn(true);
  });

  testWidgets('Login screen only offers Google sign-in', (tester) async {
    await tester.pumpWidget(_wrap(const LoginScreen()));
    expect(find.text('Đăng nhập bằng Google'), findsOneWidget);
    expect(find.text('Đăng ký'), findsNothing);
    expect(find.text('Quên mật khẩu?'), findsNothing);
  });

  testWidgets('Load delay can be started, disables inputs and stopped', (
    tester,
  ) async {
    await tester.pumpWidget(_wrap(const LoadControlScreen()));
    await tester.tap(find.textContaining('Gửi yêu cầu'));
    await tester.pump();
    expect(LoadController.instance.delayActive, isTrue);
    expect(find.textContaining('STOP'), findsOneWidget);
    expect(
      tester.widget<OutlinedButton>(find.widgetWithText(OutlinedButton, 'Bật')).onPressed,
      isNull,
    );

    await tester.tap(find.textContaining('STOP'));
    await tester.pump();
    expect(LoadController.instance.delayActive, isFalse);
    expect(find.textContaining('Gửi yêu cầu'), findsOneWidget);
  });
  testWidgets('Load toggle mirrors the load state used by the dashboard', (
    tester,
  ) async {
    await tester.pumpWidget(_wrap(const LoadControlScreen()));
    expect(find.text('Trạng thái thực tế: BẬT'), findsOneWidget);

    await tester.tap(find.text('TẮT'));
    await tester.pumpAndSettle();

    expect(LoadController.instance.isOn, isFalse);
    expect(find.text('Trạng thái thực tế: TẮT'), findsOneWidget);

    LoadController.instance.setOn(true);
    await tester.pumpAndSettle();
