  testWidgets('Load schedules are capped at three', (tester) async {
    await tester.pumpWidget(_wrap(const LoadControlScreen()));
    expect(find.text('2/3'), findsOneWidget);
    expect(find.text('Thêm lịch hẹn (2/3)'), findsOneWidget);

    await tester.ensureVisible(find.text('Thêm lịch hẹn (2/3)'));
    await tester.tap(find.text('Thêm lịch hẹn (2/3)'));
    await tester.pumpAndSettle();

    expect(find.text('Lịch hẹn 3'), findsOneWidget);
    expect(find.text('3/3'), findsOneWidget);
    expect(find.text('Thêm lịch hẹn (3/3)'), findsOneWidget);
    expect(
      tester
          .widget<OutlinedButton>(
            find.ancestor(
              of: find.text('Thêm lịch hẹn (3/3)'),
              matching: find.byType(OutlinedButton),
            ),
          )
          .onPressed,
      isNull,
    );
  });

  testWidgets('Revoking developer access hides developer and calibration UI', (
    tester,
  ) async {
    await tester.pumpWidget(_wrap(const SettingsScreen()));
    expect(find.text('Chế độ nhà phát triển'), findsOneWidget);
    await tester.ensureVisible(find.text('Thu hồi chế độ nhà phát triển'));
    await tester.tap(find.text('Thu hồi chế độ nhà phát triển'));
    await tester.pumpAndSettle();
    expect(find.text('Thu hồi'), findsOneWidget);
    await tester.tap(find.text('Thu hồi').last);
    await tester.pumpAndSettle();

    expect(DeveloperAccessController.instance.hasAccess, isFalse);
    expect(find.text('Chế độ nhà phát triển'), findsNothing);

    await tester.pumpWidget(_wrap(const SensorConfigScreen()));
    expect(find.text('Bù hiệu chuẩn · calib_offset'), findsNothing);
    expect(find.text('enabled / calib_offset'), findsNothing);
  });

  testWidgets(
    'Developer access can be restored by tapping version seven times',
    (tester) async {
      DeveloperAccessController.instance.setAccess(false);
      await tester.pumpWidget(_wrap(const SettingsScreen()));
      expect(find.text('Chế độ nhà phát triển'), findsNothing);

      for (var i = 0; i < 7; i++) {
        await tester.tap(find.text('2.0.0-demo'));
        await tester.pump();
      }
      await tester.pumpAndSettle();

      expect(DeveloperAccessController.instance.hasAccess, isTrue);
      expect(find.text('Chế độ nhà phát triển'), findsOneWidget);

      await tester.pumpWidget(_wrap(const SensorConfigScreen()));
      expect(find.text('Bù hiệu chuẩn · calib_offset'), findsOneWidget);
    },
  );

  testWidgets('Load can be renamed from the header pencil', (tester) async {
    await tester.pumpWidget(_wrap(const LoadControlScreen()));
    await tester.tap(find.byIcon(Icons.edit_rounded));
    await tester.pumpAndSettle();
    await tester.enterText(
      find.descendant(
        of: find.byType(AlertDialog),
        matching: find.byType(TextField),
      ),
      'Quạt gió',
    );
    await tester.tap(find.text('Lưu'));
    await tester.pumpAndSettle();
    expect(find.text('Load 1 · Quạt gió'), findsOneWidget);
    LoadController.instance.rename('Bơm nước');
  });

  testWidgets('Sensor management shows add button and capacity', (
    tester,
  ) async {
    await tester.pumpWidget(_wrap(const SensorCapacityScreen()));
    expect(find.text('Thêm cảm biến'), findsOneWidget);
    expect(find.text('4 / 4 đã cấu hình'), findsOneWidget);
  });
}

