import 'package:flutter/material.dart';

import '../models/device_selection.dart';
import '../models/load_control_selection.dart';
import '../navigation/app_routes.dart';
import '../services/crud_api.dart';
import '../services/device_api.dart';
import '../services/mqtt_session_manager.dart';
import '../protocol/mqtt_payloads.dart';
import '../state/load_controller.dart';
import '../state/sensors_state.dart';
import '../theme/app_colors.dart';
import '../theme/app_text_styles.dart';
import '../widgets/app_buttons.dart';
import '../widgets/app_card.dart';
import '../widgets/app_more_menu.dart';
import '../widgets/rename_dialog.dart';
import '../widgets/screen_scaffold.dart';
import '../widgets/status_chip.dart';

class DashboardScreen extends StatefulWidget {
  const DashboardScreen({super.key, required this.device, this.inShell = true});

  final DeviceSelection device;
  final bool inShell;

  @override
  State<DashboardScreen> createState() => _DashboardScreenState();
}

class _DashboardScreenState extends State<DashboardScreen> {
  int _tab = 0;
  late String _name = widget.device.name;

  Future<void> _rename() async {
    final name = await showDialog<String>(
      context: context,
      builder: (_) => RenameDialog(
        title: 'Đổi tên thiết bị',
        hint: 'Tên thiết bị',
        initial: _name,
      ),
    );
    final v = name?.trim();
    if (v == null || v.isEmpty || !mounted) return;
    setState(() => _name = v);
    await CrudApi.renameDevice(widget.device.deviceId, v);
  }

  Future<void> _emergencyStop() async {
    final messenger = ScaffoldMessenger.of(context);
    try {
      final ack = await MqttSessionManager.instance.publishCommandAndWaitForAck(
        widget.device.deviceId,
        MqttPayloads.emergencyStop(cmdId: MqttPayloads.newCommandId()),
      );
      if (!mounted) return;
      if (!ack.isSuccess) {
        messenger.showSnackBar(
          SnackBar(content: Text('Dừng khẩn cấp bị từ chối: ${ack.code}')),
        );
        return;
      }
      for (final load in LoadController.loads) {
        load.cancelDelay();
        load.setOn(false);
      }
      sensorsRunning.value = false;
      messenger.showSnackBar(
        const SnackBar(content: Text('ESP32 đã xác nhận dừng khẩn cấp')),
      );
    } catch (error) {
      if (!mounted) return;
      messenger.showSnackBar(
        SnackBar(
          content: Text('Không gửi/xác nhận được dừng khẩn cấp: $error'),
        ),
      );
    }
  }

  Future<void> _confirmDelete() async {
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        backgroundColor: AppColors.surface,
        surfaceTintColor: Colors.transparent,
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(18)),
        title: const Text('Xóa thiết bị', style: AppTextStyles.sectionTitle),
        content: Text(
          'Bạn có chắc chắn muốn xóa thiết bị $_name?',
          style: AppTextStyles.bodySecondary,
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(ctx).pop(false),
            child: Text(
              'Hủy',
              style: AppTextStyles.link.copyWith(
                color: AppColors.textSecondary,
              ),
            ),
          ),
          TextButton(
            onPressed: () => Navigator.of(ctx).pop(true),
            child: Text(
              'Đồng ý',
              style: AppTextStyles.link.copyWith(color: AppColors.errorText),
            ),
          ),
        ],
      ),
    );
    if (confirmed != true || !mounted) return;
    await DeviceApi.deleteDevice('ao_nuoi_a1');
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(content: Text('Đã gửi yêu cầu xóa thiết bị')),
    );
  }

  @override
  Widget build(BuildContext context) {
    return ScreenScaffold(
      title: 'Bảng điều khiển',
      subtitle: '$_name · Vận hành bình thường',
      showBack: true,
      embedInTab: widget.inShell,
      navIndex: widget.inShell ? null : 0,
      onNavTap: widget.inShell ? null : (i) => AppRoutes.openTab(context, i),
      headerTrailing: AppMoreMenu<String>(
        onSelected: (_) => _confirmDelete(),
        itemBuilder: (_) => const [
          PopupMenuItem(
            value: 'delete',
            child: Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                Icon(
                  Icons.delete_outline_rounded,
                  size: 20,
                  color: AppColors.errorText,
                ),
                SizedBox(width: 10),
                Text(
                  'Xóa thiết bị',
                  style: TextStyle(
                    fontSize: 14,
                    fontWeight: FontWeight.w500,
                    color: AppColors.errorText,
                  ),
                ),
              ],
            ),
          ),
        ],
      ),
      body: Column(
        children: [
          Padding(
            padding: const EdgeInsets.fromLTRB(16, 16, 16, 0),
            child: _DeviceSummaryCard(
              name: _name,
              onRename: _rename,
              onEmergencyStop: _emergencyStop,
            ),
          ),
          Padding(
            padding: const EdgeInsets.fromLTRB(16, 14, 16, 14),
            child: Row(
              children: [
                _SegChip(
                  label: 'Cảm biến',
                  selected: _tab == 0,
                  onTap: () => setState(() => _tab = 0),
                ),
                const SizedBox(width: 8),
                _SegChip(
                  label: 'Tải',
                  selected: _tab == 1,
                  onTap: () => setState(() => _tab = 1),
                ),
              ],
            ),
          ),
          Expanded(
            child: SingleChildScrollView(
              padding: const EdgeInsets.fromLTRB(16, 0, 16, 24),
              child: _tab == 0
                  ? _SensorsTab(device: widget.device)
                  : _LoadsTab(device: widget.device),
            ),
          ),
        ],
      ),
    );
  }
}

