        interfaceType: 'rs485',
        interfaceIndex: sensor.port - 1,
        sensorType: sensor.sensorType,
        name: sensor.name,
        slaveId: sensor.slaveId,
        isNew: false,
      ),
    );
    if (result is SensorConfigSelection && mounted) {
      setState(
        () => _sensors[index] = _Sensor(
          result.name,
          sensor.port,
          result.sensorType,
          result.slaveId ?? sensor.slaveId,
        ),
      );
    }
  }

  Future<void> _add() async {
    final index = _sensors.length;
    if (index >= _maxRs485) return;
    final result = await Navigator.of(context).pushNamed(
      AppRoutes.sensorConfig,
      arguments: SensorConfigSelection(
        device: widget.device,
        interfaceType: 'rs485',
        interfaceIndex: index,
        sensorType: 'ph',
        name: 'Sensor_${index + 1}',
        slaveId: index + 1,
        isNew: true,
      ),
    );
    if (result is SensorConfigSelection && mounted) {
      setState(
        () => _sensors.add(
          _Sensor(
            result.name,
            index + 1,
            result.sensorType,
            result.slaveId ?? index + 1,
          ),
        ),
      );
    }
  }

  Future<void> _configureAnalog() async {
    final result = await Navigator.of(context).pushNamed(
      AppRoutes.sensorConfig,
      arguments: SensorConfigSelection(
        device: widget.device,
        interfaceType: 'analog_4_20ma',
        interfaceIndex: 0,
        sensorType: 'analog_4_20ma',
        name: 'Analog_4_20mA',
        isNew: !_analogConfigured,
      ),
    );
    if (result is SensorConfigSelection && mounted) {
      setState(() => _analogConfigured = true);
    }
  }

  @override
  Widget build(BuildContext context) {
    return ScreenScaffold(
      showMore: false,
      title: 'Quản lý cảm biến',
      subtitle: '${widget.device.name} · ${widget.device.deviceId}',
      showBack: true,
      embedInTab: widget.inShell,
      navIndex: widget.inShell ? null : 0,
      onNavTap: widget.inShell ? null : (i) => AppRoutes.openTab(context, i),
      body: SingleChildScrollView(
        padding: const EdgeInsets.fromLTRB(16, 16, 16, 24),
        child: Column(
          children: [
            _CapacityCard(used: _sensors.length),
            for (final sensor in _sensors) ...[
              const SizedBox(height: 12),
              _SensorItem(
                name: sensor.name,
                port: sensor.port,
                onEdit: () => _edit(_sensors.indexOf(sensor)),
              ),
            ],
            const SizedBox(height: 12),
            if (_hasAnalog)
              AppCard(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    const Text(
                      'Analog 4–20 mA',
                      style: AppTextStyles.cardTitle,
                    ),
                    const SizedBox(height: 6),
                    Text(
                      'Khả năng phần cứng: 1 · Đã dùng: ${_analogConfigured ? 1 : 0}',
                      style: AppTextStyles.bodySecondary,
                    ),
                    const SizedBox(height: 12),
                    OutlineAppButton(
                      label: _analogConfigured
                          ? 'Sửa cấu hình'
                          : 'Cấu hình cảm biến',
                      height: 46,
                      onPressed: _configureAnalog,
                    ),
                  ],
                ),
              ),
            const SizedBox(height: 12),
            if (_isFull)
              const GhostButton(label: 'Thêm cảm biến', onPressed: null)
            else
              OutlineAppButton(
                label: 'Thêm cảm biến',
                icon: Icons.add,
                onPressed: _add,
              ),
          ],
        ),
      ),
    );
  }
}

class _CapacityCard extends StatelessWidget {
  const _CapacityCard({required this.used});

  final int used;

  @override
  Widget build(BuildContext context) {
    final free = _maxRs485 - used;
    return AppCard(
      color: AppColors.mint,
      borderColor: AppColors.primarySoft,
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              const Expanded(
                child: Text(
                  'Dung lượng RS485',
                  style: AppTextStyles.bodySecondary,
                ),
              ),
              Text('$used / $_maxRs485 đã cấu hình', style: AppTextStyles.mono),
            ],
          ),
          const SizedBox(height: 8),
          Padding(
            padding: const EdgeInsets.only(left: 10),
            child: Text(
              free == 0 ? 'Đã dùng hết dung lượng' : 'Còn $free cổng trống',
              style: AppTextStyles.chip.copyWith(color: AppColors.primary),
            ),
          ),
          const SizedBox(height: 8),
          Text(
            free == 0
                ? 'Không còn cổng RS485 trống. Chỉ có thể sửa các cảm biến đã cấu hình.'
                : 'Còn cổng RS485 trống. Có thể thêm cảm biến mới.',
            style: AppTextStyles.caption,
          ),
        ],
      ),
    );
  }
}

class _SensorItem extends StatelessWidget {
  const _SensorItem({
    required this.name,
    required this.port,
    required this.onEdit,
  });

  final String name;
  final int port;
  final VoidCallback onEdit;

  @override
  Widget build(BuildContext context) {
    return AppCard(
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Expanded(child: Text(name, style: AppTextStyles.cardTitle)),
              const StatusChip(label: 'Đã bật', kind: StatusKind.enabled),
            ],
          ),
          const SizedBox(height: 6),
          Text('Port number: $port', style: AppTextStyles.mono),
          const SizedBox(height: 12),
          OutlineAppButton(
            label: 'Sửa cấu hình',
            height: 46,
            onPressed: onEdit,
          ),
        ],
      ),
    );
  }
}

