import 'package:flutter/material.dart';

import '../models/device_selection.dart';
import '../navigation/app_routes.dart';
import '../protocol/mqtt_ack.dart';
import '../protocol/mqtt_payloads.dart';
import '../services/mqtt_session_manager.dart';
import '../state/load_controller.dart';
import '../theme/app_colors.dart';
import '../theme/app_text_styles.dart';
import '../widgets/app_card.dart';
import '../widgets/app_text_field.dart';
import '../widgets/rename_dialog.dart';
import '../widgets/screen_scaffold.dart';

enum _AutomationMode { none, weekly, sensor }

class LoadControlScreen extends StatefulWidget {
  const LoadControlScreen({
    super.key,
    required this.device,
    required this.load,
    this.inShell = true,
  });

  final DeviceSelection device;
  final LoadController load;
  final bool inShell;

  @override
  State<LoadControlScreen> createState() => _LoadControlScreenState();
}

class _LoadControlScreenState extends State<LoadControlScreen> {
  final _delay = TextEditingController(text: '5');
  final _duration = TextEditingController(text: '60');
  final _onThreshold = TextEditingController(text: '10');
  final _offThreshold = TextEditingController(text: '20');
  final _selectedDays = <int>{0, 1, 2, 3, 4};
  final _weekdays = const ['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'];

  TimeOfDay _onTime = const TimeOfDay(hour: 6, minute: 0);
  TimeOfDay _offTime = const TimeOfDay(hour: 18, minute: 0);
  _AutomationMode _mode = _AutomationMode.none;
  bool _turnOnFirst = true;
  late bool _policyEnabled = widget.load.enabled;
  bool _onConditionEnabled = false;
  bool _offConditionEnabled = false;
  String _onSensorId = 'sensor_001';
  String _offSensorId = 'sensor_001';
  String _onOperator = 'lt';
  String _offOperator = 'gte';
  bool _sending = false;

  LoadController get _load => widget.load;

  @override
  void dispose() {
    _delay.dispose();
    _duration.dispose();
    _onThreshold.dispose();
    _offThreshold.dispose();
    super.dispose();
  }

  Future<void> _withAck(
    Future<MqttAck> Function() send, {
    required String successMessage,
  }) async {
    if (_sending) return;
    setState(() => _sending = true);
    try {
      final ack = await send();
      if (!mounted) return;
      if (!ack.isSuccess) {
        throw StateError('ESP32 từ chối yêu cầu: ${ack.code}');
      }
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(SnackBar(content: Text(successMessage)));
    } catch (error) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Giao tiếp với ESP32 thất bại: $error')),
      );
    } finally {
      if (mounted) setState(() => _sending = false);
    }
  }

  Future<void> _setStateOnDevice(bool state) async {
    final payload = MqttPayloads.setState(
      cmdId: MqttPayloads.newCommandId(),
      loadId: _load.id,
      state: state,
    );
    await _withAck(() async {
      final ack = await MqttSessionManager.instance.publishCommandAndWaitForAck(
        widget.device.deviceId,
        payload,
      );
      if (ack.isSuccess) _load.setOn(state);
      return ack;
    }, successMessage: 'ESP32 đã xác nhận tải ${state ? 'BẬT' : 'TẮT'}.');
  }

  Future<void> _sendCycle() async {
    final delayMin = int.tryParse(_delay.text.trim());
    final durationMin = int.tryParse(_duration.text.trim());
    if (delayMin == null || durationMin == null) {
      _showError('Thời gian trễ và thời lượng phải là số nguyên phút.');
      return;
    }
    final payload = MqttPayloads.setLoadCycle(
      cmdId: MqttPayloads.newCommandId(),
      loadId: _load.id,
      turnOnFirst: _turnOnFirst,
      delayMin: delayMin,
      durationMin: durationMin,
    );
    await _withAck(() async {
      final ack = await MqttSessionManager.instance.publishCommandAndWaitForAck(
        widget.device.deviceId,
        payload,
      );
      if (ack.isSuccess) {
        _load.startDelay(
          turnOn: _turnOnFirst,
          duration: Duration(minutes: delayMin),
        );
      }
      return ack;
    }, successMessage: 'ESP32 đã xác nhận chu kỳ điều khiển.');
  }

  Future<void> _savePolicy({bool? enabled}) async {
    final nextEnabled = enabled ?? _policyEnabled;
    final weekly = nextEnabled && _mode == _AutomationMode.weekly;
    final sensorRules = nextEnabled && _mode == _AutomationMode.sensor;
    final schedule = weekly ? _utcSchedule() : null;
    if (weekly && schedule == null) return;
    final onThreshold = double.tryParse(_onThreshold.text.trim());
    final offThreshold = double.tryParse(_offThreshold.text.trim());
    if (onThreshold == null || offThreshold == null) {
      _showError('Ngưỡng cảm biến phải là số hữu hạn.');
      return;
    }
    final payload = MqttPayloads.setLoadControl(
      cmdId: MqttPayloads.newCommandId(),
      loadId: _load.id,
      enabled: nextEnabled,
      scheduleEnabled: weekly,
      daysMask: schedule?.daysMask ?? 0,
      onTimeUtc: schedule?.onTime ?? '06:00',
      offTimeUtc: schedule?.offTime ?? '18:00',
      onConditionEnabled: sensorRules && _onConditionEnabled,
      onSensorId: _onSensorId,
      onOperator: _onOperator,
      onThreshold: onThreshold,
      offConditionEnabled: sensorRules && _offConditionEnabled,
      offSensorId: _offSensorId,
      offOperator: _offOperator,
      offThreshold: offThreshold,
    );
    await _withAck(
      () async {
        final ack = await MqttSessionManager.instance
            .publishConfigAndWaitForAck(widget.device.deviceId, payload);
        if (ack.isSuccess) {
          _policyEnabled = nextEnabled;
          _load.setEnabled(nextEnabled);
          if (!nextEnabled) {
            _mode = _AutomationMode.none;
            _onConditionEnabled = false;
            _offConditionEnabled = false;
            _selectedDays.clear();
          }
        }
        return ack;
      },
      successMessage: nextEnabled
          ? 'ESP32 đã xác nhận cấu hình tải.'
          : 'ESP32 đã xác nhận khóa tải và xóa automation.',
    );
  }

  ({String onTime, String offTime, int daysMask})? _utcSchedule() {
    if (_selectedDays.isEmpty) {
      _showError('Chọn ít nhất một ngày cho lịch tuần.');
      return null;
    }
    final onTimes = <String>{};
    final offTimes = <String>{};
    var utcDaysMask = 0;
    final today = DateTime.now();
    for (final localWeekday in _selectedDays) {
      final daysAhead = (localWeekday + 1 - today.weekday + 7) % 7;
      final localDate = DateTime(
        today.year,
        today.month,
        today.day + daysAhead,
      );
      final onLocal = DateTime(
        localDate.year,
        localDate.month,
        localDate.day,
        _onTime.hour,
        _onTime.minute,
      );
      final offLocal = DateTime(
        localDate.year,
        localDate.month,
        localDate.day,
        _offTime.hour,
        _offTime.minute,
      );
      final onUtc = onLocal.toUtc();
      final offUtc = offLocal.toUtc();
      onTimes.add(_formatTime(onUtc));
      offTimes.add(_formatTime(offUtc));
      utcDaysMask |= 1 << (onUtc.weekday - 1);
    }
    if (onTimes.length != 1 || offTimes.length != 1) {
      _showError(
        'Các ngày đã chọn có múi giờ UTC khác nhau; hãy lưu từng lịch riêng hoặc chọn ngày khác.',
      );
      return null;
    }
    return (
      onTime: onTimes.single,
      offTime: offTimes.single,
      daysMask: utcDaysMask,
    );
  }

  String _formatTime(DateTime time) =>
      '${time.hour.toString().padLeft(2, '0')}:'
      '${time.minute.toString().padLeft(2, '0')}';

  Future<void> _pickTime(bool isOnTime) async {
    final selected = await showTimePicker(
      context: context,
      initialTime: isOnTime ? _onTime : _offTime,
    );
    if (selected == null || !mounted) return;
    setState(() {
      if (isOnTime) {
        _onTime = selected;
      } else {
        _offTime = selected;
      }
    });
  }

  Future<void> _rename() async {
    final newName = await showDialog<String>(
      context: context,
      builder: (_) => RenameDialog(
        title: 'Đổi tên tải',
        hint: 'Tên tải',
        initial: _load.name,
      ),
    );
    final name = newName?.trim();
    if (name == null || name.isEmpty || !mounted) return;
    final payload = MqttPayloads.setLoadName(
      cmdId: MqttPayloads.newCommandId(),
      loadId: _load.id,
      name: name,
    );
    await _withAck(() async {
      final ack = await MqttSessionManager.instance.publishConfigAndWaitForAck(
        widget.device.deviceId,
        payload,
      );
      if (ack.isSuccess) _load.rename(name);
      return ack;
    }, successMessage: 'ESP32 đã xác nhận tên tải.');
  }

  void _showError(String message) {
    ScaffoldMessenger.of(
      context,
    ).showSnackBar(SnackBar(content: Text(message)));
  }

  Widget _timeButton(String label, TimeOfDay time, VoidCallback onPressed) =>
      OutlinedButton(
        onPressed: _sending ? null : onPressed,
        child: Text('$label · ${time.format(context)}'),
      );

  Widget _buildWeeklySchedule() => Column(
    crossAxisAlignment: CrossAxisAlignment.start,
    children: [
      Wrap(
        spacing: 4,
        children: [
          for (var day = 0; day < _weekdays.length; day++)
            FilterChip(
              label: Text(_weekdays[day]),
              selected: _selectedDays.contains(day),
              onSelected: _sending
                  ? null
                  : (selected) => setState(
                      () => selected
                          ? _selectedDays.add(day)
                          : _selectedDays.remove(day),
                    ),
            ),
        ],
      ),
      Row(
        children: [
          Expanded(child: _timeButton('Bật', _onTime, () => _pickTime(true))),
          const SizedBox(width: 8),
          Expanded(child: _timeButton('Tắt', _offTime, () => _pickTime(false))),
        ],
      ),
      const Text(
        'Giờ nhập theo múi giờ điện thoại; ứng dụng chuyển sang UTC để gửi.',
        style: AppTextStyles.caption,
      ),
    ],
  );

  Widget _conditionRow({
    required String label,
    required bool enabled,
    required ValueChanged<bool> onEnabled,
    required String sensorId,
    required ValueChanged<String?> onSensorChanged,
    required String operator,
    required ValueChanged<String?> onOperatorChanged,
    required TextEditingController threshold,
  }) => AppCard(
    child: Column(
      children: [
        SwitchListTile(
          contentPadding: EdgeInsets.zero,
          title: Text(label),
          value: enabled,
          onChanged: _sending ? null : onEnabled,
        ),
        if (enabled) ...[
          DropdownButtonFormField<String>(
            initialValue: sensorId,
            decoration: const InputDecoration(labelText: 'Cảm biến'),
            items: [
              for (var id = 1; id <= 5; id++)
                DropdownMenuItem(
                  value: 'sensor_${id.toString().padLeft(3, '0')}',
                  child: Text('sensor_${id.toString().padLeft(3, '0')}'),
                ),
            ],
            onChanged: _sending ? null : onSensorChanged,
          ),
          DropdownButtonFormField<String>(
            initialValue: operator,
            decoration: const InputDecoration(labelText: 'Toán tử'),
            items: const [
              DropdownMenuItem(value: 'lt', child: Text('<')),
              DropdownMenuItem(value: 'lte', child: Text('≤')),
              DropdownMenuItem(value: 'eq', child: Text('=')),
              DropdownMenuItem(value: 'gte', child: Text('≥')),
              DropdownMenuItem(value: 'gt', child: Text('>')),
            ],
            onChanged: _sending ? null : onOperatorChanged,
          ),
          AppTextField(
            label: 'Ngưỡng',
            controller: threshold,
            keyboardType: const TextInputType.numberWithOptions(
              decimal: true,
              signed: true,
            ),
          ),
        ],
      ],
    ),
  );

  @override
  Widget build(BuildContext context) => ListenableBuilder(
    listenable: _load,
    builder: (context, _) => ScreenScaffold(
      title: _load.title,
      subtitle: '${widget.device.name} · ${widget.device.deviceId}',
      showBack: true,
      embedInTab: widget.inShell,
      navIndex: widget.inShell ? null : 0,
      onNavTap: widget.inShell ? null : (i) => AppRoutes.openTab(context, i),
      titleTrailing: IconButton(
        onPressed: _sending ? null : _rename,
        tooltip: 'Đổi tên tải',
        icon: const Icon(Icons.edit_rounded, color: AppColors.primary),
      ),
      body: SingleChildScrollView(
        padding: const EdgeInsets.fromLTRB(16, 16, 16, 24),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            AppCard(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text('Tải ${_load.id}', style: AppTextStyles.cardTitle),
                  Text(
                    'Trạng thái gần nhất: ${_load.isOn ? 'BẬT' : 'TẮT'}',
                    style: AppTextStyles.bodySecondary,
                  ),
                  SwitchListTile(
                    contentPadding: EdgeInsets.zero,
                    title: const Text('Cho phép điều khiển tải'),
                    value: _policyEnabled,
                    onChanged: _sending
                        ? null
                        : (value) => _savePolicy(enabled: value),
                  ),
                  Wrap(
                    spacing: 8,
                    children: [
                      FilledButton(
                        onPressed: _sending || !_policyEnabled
                            ? null
                            : () => _setStateOnDevice(true),
                        child: const Text('Bật ngay'),
                      ),
                      OutlinedButton(
                        onPressed: _sending
                            ? null
                            : () => _setStateOnDevice(false),
                        child: const Text('Tắt ngay'),
                      ),
                    ],
                  ),
                ],
              ),
            ),
            const SizedBox(height: 16),
            Text('Chu kỳ một lần', style: AppTextStyles.sectionTitle),
            const SizedBox(height: 8),
            AppCard(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  SegmentedButton<bool>(
                    segments: const [
                      ButtonSegment(value: true, label: Text('Bật rồi tắt')),
                      ButtonSegment(value: false, label: Text('Tắt rồi bật')),
                    ],
                    selected: {_turnOnFirst},
                    onSelectionChanged: _sending
                        ? null
                        : (selection) =>
                              setState(() => _turnOnFirst = selection.single),
                  ),
                  const SizedBox(height: 10),
                  AppTextField(
                    label: 'Thời gian trễ (phút)',
                    controller: _delay,
                    keyboardType: TextInputType.number,
                  ),
                  AppTextField(
                    label: 'Thời lượng pha tiếp theo (phút; 0 = một lần)',
                    controller: _duration,
                    keyboardType: TextInputType.number,
                  ),
                  Align(
                    alignment: Alignment.centerRight,
                    child: FilledButton(
                      onPressed: _sending || !_policyEnabled
                          ? null
                          : _sendCycle,
                      child: const Text('Gửi chu kỳ'),
                    ),
                  ),
                ],
              ),
            ),
            const SizedBox(height: 16),
            Text('Lịch / điều kiện tự động', style: AppTextStyles.sectionTitle),
            const SizedBox(height: 8),
            AppCard(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  DropdownButtonFormField<_AutomationMode>(
                    initialValue: _mode,
                    decoration: const InputDecoration(labelText: 'Chế độ'),
                    items: const [
                      DropdownMenuItem(
                        value: _AutomationMode.none,
                        child: Text('Không dùng automation'),
                      ),
                      DropdownMenuItem(
                        value: _AutomationMode.weekly,
                        child: Text('Lịch tuần'),
                      ),
                      DropdownMenuItem(
                        value: _AutomationMode.sensor,
                        child: Text('Điều kiện cảm biến'),
                      ),
                    ],
                    onChanged: _sending
                        ? null
                        : (value) {
                            if (value != null) setState(() => _mode = value);
                          },
                  ),
                  if (_mode == _AutomationMode.weekly) _buildWeeklySchedule(),
                  if (_mode == _AutomationMode.sensor) ...[
                    _conditionRow(
                      label: 'Điều kiện bật',
                      enabled: _onConditionEnabled,
                      onEnabled: (value) =>
                          setState(() => _onConditionEnabled = value),
                      sensorId: _onSensorId,
                      onSensorChanged: (value) {
                        if (value != null) setState(() => _onSensorId = value);
                      },
                      operator: _onOperator,
                      onOperatorChanged: (value) {
                        if (value != null) setState(() => _onOperator = value);
                      },
                      threshold: _onThreshold,
                    ),
                    _conditionRow(
                      label: 'Điều kiện tắt',
                      enabled: _offConditionEnabled,
                      onEnabled: (value) =>
                          setState(() => _offConditionEnabled = value),
                      sensorId: _offSensorId,
                      onSensorChanged: (value) {
                        if (value != null) setState(() => _offSensorId = value);
                      },
                      operator: _offOperator,
                      onOperatorChanged: (value) {
                        if (value != null) setState(() => _offOperator = value);
                      },
                      threshold: _offThreshold,
                    ),
                  ],
                  const SizedBox(height: 12),
                  Align(
                    alignment: Alignment.centerRight,
                    child: FilledButton(
                      onPressed: _sending ? null : () => _savePolicy(),
                      child: Text(
                        _sending ? 'Đang chờ ACK...' : 'Lưu cấu hình tải',
                      ),
                    ),
                  ),
                ],
              ),
            ),
          ],
        ),
      ),
    ),
  );
}

