import 'dart:math';
import 'dart:convert';

class MqttPayloads {
  MqttPayloads._();

  static const version = 1;
  static final _random = Random.secure();
  static final _cmdIdPattern = RegExp(r'^[A-Za-z0-9_-]{1,36}$');
  static final _sensorIdPattern = RegExp(r'^sensor_00[1-5]$');
  static const _operators = {'lt', 'lte', 'eq', 'gte', 'gt'};

  static String newCommandId() {
    final bytes = List<int>.generate(16, (_) => _random.nextInt(256));
    bytes[6] = (bytes[6] & 0x0f) | 0x40;
    bytes[8] = (bytes[8] & 0x3f) | 0x80;
    final hex = bytes
        .map((byte) => byte.toRadixString(16).padLeft(2, '0'))
        .join();
    return '${hex.substring(0, 8)}-${hex.substring(8, 12)}-'
        '${hex.substring(12, 16)}-${hex.substring(16, 20)}-'
        '${hex.substring(20)}';
  }

  static Map<String, Object?> setState({
    required String cmdId,
    required int loadId,
    required bool state,
    int durationMin = 0,
  }) {
    _validateCommand(cmdId);
    _validateLoadId(loadId);
    if (durationMin < 0 ||
        durationMin > 86400 ||
        (!state && durationMin != 0)) {
      throw ArgumentError.value(durationMin, 'durationMin');
    }
    return {
      'v': version,
      'cmd_id': cmdId,
      'action': 'SET_STATE',
      'load_id': loadId,
      'state': state,
      'duration_min': durationMin,
    };
  }

  static Map<String, Object?> emergencyStop({required String cmdId}) {
    _validateCommand(cmdId);
    return {'v': version, 'cmd_id': cmdId, 'action': 'EMERGENCY_STOP'};
  }

  static Map<String, Object?> emergencyRelease({required String cmdId}) {
    _validateCommand(cmdId);
    return {
      'v': version,
      'cmd_id': cmdId,
      'action': 'EMERGENCY_RELEASE',
      'confirm': true,
    };
  }

  static Map<String, Object?> setLoadCycle({
    required String cmdId,
    required int loadId,
    required bool turnOnFirst,
    required int delayMin,
    required int durationMin,
  }) {
    _validateCommand(cmdId);
    _validateLoadId(loadId);
    if (delayMin < 0 ||
        delayMin > 1440 ||
        durationMin < 0 ||
        durationMin > 1440) {
      throw ArgumentError('Cycle delay and duration must be 0..1440 minutes');
    }
    return {
      'v': version,
      'cmd_id': cmdId,
      'action': 'SET_LOAD_CYCLE',
      'load_id': loadId,
      'mode': turnOnFirst ? 'ON_THEN_OFF' : 'OFF_THEN_ON',
      if (turnOnFirst) 'on_delay_min': delayMin else 'off_delay_min': delayMin,
      'duration': durationMin,
    };
  }

  static Map<String, Object?> setSensorConfig({
    required String cmdId,
    required String interfaceType,
    required int interfaceIndex,
    required String sensorType,
    required String name,
    required bool enabled,
    required double calibrationOffset,
    int? slaveId,
  }) {
    _validateCommand(cmdId);
    _validateName(name);
    if (!calibrationOffset.isFinite ||
        calibrationOffset < -100 ||
        calibrationOffset > 100) {
      throw ArgumentError.value(calibrationOffset, 'calibrationOffset');
    }
    if (interfaceType == 'rs485') {
      if (interfaceIndex < 0 ||
          interfaceIndex > 3 ||
          !const {'sht40', 'do', 'ph'}.contains(sensorType) ||
          slaveId == null ||
          slaveId < 1 ||
          slaveId > 247) {
        throw ArgumentError('Invalid RS485 sensor configuration');
      }
    } else if (interfaceType == 'analog_4_20ma') {
      if (interfaceIndex != 0 ||
          sensorType != 'analog_4_20ma' ||
          slaveId != null) {
        throw ArgumentError('Invalid analog sensor configuration');
      }
    } else {
      throw ArgumentError.value(interfaceType, 'interfaceType');
    }
    return {
      'v': version,
      'cmd_id': cmdId,
      'type': 'sensor',
      'interface_type': interfaceType,
      'interface_index': interfaceIndex,
      'sensor_type': sensorType,
      if (slaveId case final value?) 'slave_id': value,
      'name': name,
      'enabled': enabled,
      'calib_offset': calibrationOffset,
    };
  }

  static Map<String, Object?> setLoadName({
    required String cmdId,
    required int loadId,
    required String name,
  }) {
    _validateCommand(cmdId);
    _validateLoadId(loadId);
    _validateName(name);
    return {
      'v': version,
      'cmd_id': cmdId,
      'type': 'load_name',
      'load_id': loadId,
      'name': name,
    };
  }

  static Map<String, Object?> setLoadControl({
    required String cmdId,
    required int loadId,
    required bool enabled,
    required bool scheduleEnabled,
    required int daysMask,
    required String onTimeUtc,
    required String offTimeUtc,
    required bool onConditionEnabled,
    required String onSensorId,
    required String onOperator,
    required double onThreshold,
    required bool offConditionEnabled,
    required String offSensorId,
    required String offOperator,
    required double offThreshold,
  }) {
    _validateCommand(cmdId);
    _validateLoadId(loadId);
    _validateTime(onTimeUtc, 'onTimeUtc');
    _validateTime(offTimeUtc, 'offTimeUtc');
    _validateCondition(onSensorId, onOperator, onThreshold, 'on');
    _validateCondition(offSensorId, offOperator, offThreshold, 'off');
    if (daysMask < 0 || daysMask > 127 || (scheduleEnabled && daysMask == 0)) {
      throw ArgumentError.value(daysMask, 'daysMask');
    }
    if (scheduleEnabled && (onConditionEnabled || offConditionEnabled)) {
      throw ArgumentError(
        'Weekly schedule and sensor conditions cannot both be enabled',
      );
    }
    if (!enabled &&
        (scheduleEnabled || onConditionEnabled || offConditionEnabled)) {
      throw ArgumentError(
        'A disabled load cannot have an active schedule or sensor condition',
      );
    }
    return {
      'v': version,
      'cmd_id': cmdId,
      'type': 'load_control',
      'load_id': loadId,
      'enabled': enabled,
      'schedule_enabled': scheduleEnabled,
      'days_mask': daysMask,
      'on_time_utc': onTimeUtc,
      'off_time_utc': offTimeUtc,
      'on_condition_enabled': onConditionEnabled,
      'on_sensor_id': onSensorId,
      'on_operator': onOperator,
      'on_threshold': onThreshold,
      'off_condition_enabled': offConditionEnabled,
      'off_sensor_id': offSensorId,
      'off_operator': offOperator,
      'off_threshold': offThreshold,
    };
  }

  static void _validateCommand(String cmdId) {
    if (!_cmdIdPattern.hasMatch(cmdId)) {
      throw ArgumentError.value(cmdId, 'cmdId');
    }
  }

  static void _validateLoadId(int loadId) {
    if (loadId < 1 || loadId > 4) {
      throw ArgumentError.value(loadId, 'loadId');
    }
  }

  static void _validateName(String name) {
    final encodedLength = utf8.encode(name).length;
    if (name.isEmpty ||
        encodedLength > 31 ||
        name.trim() != name ||
        name.codeUnits.any((unit) => unit < 0x20 || unit == 0x7f)) {
      throw ArgumentError.value(name, 'name');
    }
  }

  static void _validateTime(String value, String name) {
    final match = RegExp(r'^([01]\d|2[0-3]):[0-5]\d$').hasMatch(value);
    if (!match) throw ArgumentError.value(value, name);
  }

  static void _validateCondition(
    String sensorId,
    String operator,
    double threshold,
    String prefix,
  ) {
    if (!_sensorIdPattern.hasMatch(sensorId) ||
        !_operators.contains(operator) ||
        !threshold.isFinite ||
        threshold < -1000000 ||
        threshold > 1000000) {
      throw ArgumentError('Invalid $prefix sensor condition');
    }
  }
}

