import 'package:flutter/material.dart';

import '../models/device_selection.dart';
import '../navigation/app_routes.dart';
import '../protocol/mqtt_payloads.dart';
import '../services/mqtt_session_manager.dart';
import '../theme/app_text_styles.dart';
import '../widgets/app_buttons.dart';
import '../widgets/app_card.dart';
import '../widgets/app_text_field.dart';
import '../widgets/screen_scaffold.dart';

class SensorConfigScreen extends StatefulWidget {
  const SensorConfigScreen({
    super.key,
    required this.selection,
    this.inShell = true,
  });

  final SensorConfigSelection selection;
  final bool inShell;

  @override
  State<SensorConfigScreen> createState() => _SensorConfigScreenState();
}

class _SensorConfigScreenState extends State<SensorConfigScreen> {
  late String _sensorType = widget.selection.sensorType;
  late bool _enabled = widget.selection.enabled;
  late final _slave = TextEditingController(
    text: widget.selection.slaveId?.toString() ?? '1',
  );
  late final _name = TextEditingController(text: widget.selection.name);
  late final _offset = TextEditingController(
    text: widget.selection.calibrationOffset.toString(),
  );
  bool _sending = false;

  @override
  void dispose() {
    _slave.dispose();
    _name.dispose();
    _offset.dispose();
    super.dispose();
  }

  Future<bool> _save({bool closeOnSuccess = false}) async {
    if (_sending) return false;
    setState(() => _sending = true);
    try {
      final selection = widget.selection;
      final payload = MqttPayloads.setSensorConfig(
        cmdId: MqttPayloads.newCommandId(),
        interfaceType: selection.interfaceType,
        interfaceIndex: selection.interfaceIndex,
        sensorType: _sensorType,
        name: _name.text.trim(),
        enabled: _enabled,
        calibrationOffset:
            double.tryParse(_offset.text.trim()) ??
