import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:flutter_app/models/device_selection.dart';
import 'package:flutter_app/screens/load_control_screen.dart';
import 'package:flutter_app/screens/login_screen.dart';
import 'package:flutter_app/screens/sensor_capacity_screen.dart';
import 'package:flutter_app/screens/sensor_config_screen.dart';
import 'package:flutter_app/screens/settings_screen.dart';
import 'package:flutter_app/state/developer_access_controller.dart';
import 'package:flutter_app/state/load_controller.dart';
import 'package:flutter_app/theme/app_theme.dart';

const _device = DeviceSelection(deviceId: 'aabbccddeeff', name: 'Test pond');

Widget _wrap(Widget child) => MaterialApp(theme: AppTheme.light, home: child);

Widget _loadScreen() =>
    LoadControlScreen(device: _device, load: LoadController.instance);

Widget _sensorConfigScreen() => SensorConfigScreen(
  selection: SensorConfigSelection(
    device: _device,
    interfaceType: 'rs485',
    interfaceIndex: 2,
    sensorType: 'ph',
    name: 'pH Tank A1',
    isNew: false,
    slaveId: 3,
  ),
);

void main() {
  setUp(() {
    DeveloperAccessController.instance.setAccess(true);
    LoadController.instance
      ..setEnabled(true)
      ..setOn(true);
  });

  testWidgets('Login screen only offers Google sign-in', (tester) async {
    await tester.pumpWidget(_wrap(const LoginScreen()));
    expect(find.text('Đăng nhập bằng Google'), findsOneWidget);
    expect(find.text('Đăng ký'), findsNothing);
    expect(find.text('Quên mật khẩu?'), findsNothing);
  });

  testWidgets('Load screen exposes firmware command and config controls', (
    tester,
  ) async {
    await tester.pumpWidget(_wrap(_loadScreen()));
    expect(find.text('Bật ngay'), findsOneWidget);
    expect(find.text('Tắt ngay'), findsOneWidget);
    expect(find.text('Gửi chu kỳ'), findsOneWidget);
    expect(find.text('Lịch / điều kiện tự động'), findsOneWidget);
    expect(find.text('Lưu cấu hình tải'), findsOneWidget);
    expect(find.textContaining(_device.deviceId), findsOneWidget);
  });

  testWidgets('Automation mode offers weekly schedule or sensor rules', (
    tester,
  ) async {
    await tester.pumpWidget(_wrap(_loadScreen()));
    await tester.ensureVisible(find.text('Không dùng automation'));
    await tester.tap(find.text('Không dùng automation'));
    await tester.pumpAndSettle();
    await tester.tap(find.text('Lịch tuần').last);
    await tester.pumpAndSettle();
    expect(
      find.text(
        'Giờ nhập theo múi giờ điện thoại; ứng dụng chuyển sang UTC để gửi.',
      ),
      findsOneWidget,
    );
    expect(find.text('T2'), findsOneWidget);

    await tester.tap(find.text('Lịch tuần'));
    await tester.pumpAndSettle();
    await tester.tap(find.text('Điều kiện cảm biến').last);
    await tester.pumpAndSettle();
    expect(find.text('Điều kiện bật'), findsOneWidget);
    expect(find.text('Điều kiện tắt'), findsOneWidget);
  });

  testWidgets(
    'Sensor screen identifies device slot and supported sensor types',
    (tester) async {
      await tester.pumpWidget(_wrap(_sensorConfigScreen()));
      expect(find.textContaining(_device.deviceId), findsOneWidget);
      expect(find.text('Cổng 3 · rs485'), findsOneWidget);
      expect(find.text('SHT40'), findsOneWidget);
      expect(find.text('DO'), findsOneWidget);
      expect(find.text('PH'), findsOneWidget);
      expect(find.text('Địa chỉ Modbus · slave_id'), findsOneWidget);
      expect(find.text('Gửi cấu hình'), findsOneWidget);
    },
  );

  testWidgets('Sensor management shows hardware capacity', (tester) async {
    await tester.pumpWidget(_wrap(const SensorCapacityScreen(device: _device)));
    expect(find.text('Thêm cảm biến'), findsOneWidget);
    expect(find.text('4 / 4 đã cấu hình'), findsOneWidget);
  });

  testWidgets('Developer access can be revoked and restored', (tester) async {
    await tester.pumpWidget(_wrap(const SettingsScreen()));
    expect(find.text('Chế độ nhà phát triển'), findsOneWidget);
    await tester.ensureVisible(find.text('Thu hồi chế độ nhà phát triển'));
    await tester.tap(find.text('Thu hồi chế độ nhà phát triển'));
    await tester.pumpAndSettle();
    await tester.tap(find.text('Thu hồi').last);
    await tester.pumpAndSettle();
    expect(DeveloperAccessController.instance.hasAccess, isFalse);

    await tester.pumpWidget(_wrap(_sensorConfigScreen()));
    expect(find.text('Bù hiệu chuẩn · calib_offset'), findsOneWidget);
  });
}

