import 'dart:convert';

import 'package:flutter/material.dart';

import '../navigation/app_routes.dart';
import '../theme/app_colors.dart';
import '../theme/app_text_styles.dart';
import '../widgets/app_card.dart';
import '../widgets/screen_scaffold.dart';
import '../widgets/status_chip.dart';

class ConsoleArgs {
  const ConsoleArgs({required this.name, required this.deviceId});

  final String name;
  final String deviceId;
}

class _LogEntry {
  const _LogEntry({
    required this.time,
    required this.direction,
    required this.channel,
    required this.type,
    required this.hint,
    this.summary,
    required this.topic,
    this.payload,
  });

  final String time;
  final String direction;
  final String channel;
  final String type;
  final String hint;
  final String? summary;
  final String topic;
  final Map<String, Object?>? payload;

  String get header => '$time  $direction · $channel · $type';

  String get preview => summary ?? jsonEncode(payload);

  String? get prettyPayload => payload == null
      ? null
      : const JsonEncoder.withIndent('  ').convert(payload);
}

const _basePath = 'v1/usr_99218472/devices/912a00000001';

const _sampleEntries = <_LogEntry>[
  _LogEntry(
    time: '09:35:01',
    direction: 'RX',
    channel: 'BLE',
    type: 'BLE',
    hint: 'Endpoint: prov-config',
    topic: 'Endpoint: prov-config',
    payload: {'status': 'SUCCESS'},
  ),
  _LogEntry(
    time: '09:39:55',
    direction: 'RX',
    channel: 'MQTT',
    type: 'Status',
    hint: 'v1/…/status',
    summary: 'Payload status chưa có mẫu',
    topic: '$_basePath/status',
  ),
  _LogEntry(
    time: '09:39:58',
    direction: 'RX',
    channel: 'MQTT',
    type: 'Telemetry',
    hint: 'V1/…/telemetry',
    summary: 'Payload telemetry chờ firmware chốt',
    topic: '$_basePath/telemetry',
  ),
  _LogEntry(
    time: '09:40:20',
    direction: 'TX',
    channel: 'MQTT',
    type: 'Config',
    hint: 'v1/…/config/set · sensor',
    topic: '$_basePath/config/set',
    payload: {
      'v': 1,
      'cmd_id': 'sensor-01',
      'type': 'sensor',
      'interface_type': 'rs485',
      'interface_index': 2,
      'sensor_type': 'ph',
      'slave_id': 3,
      'name': 'pH_Tank_A1',
      'enabled': true,
      'calib_offset': -0.15,
    },
  ),
  _LogEntry(
    time: '09:41:05',
    direction: 'TX',
    channel: 'MQTT',
    type: 'Command',
    hint: 'v1/…/commands · load-ctrl',
    summary: 'SET_STATE · Load 1 · 1 phút',
    topic: '$_basePath/commands',
    payload: {
      'v': 1,
      'cmd_id': 'state-01',
      'action': 'SET_STATE',
      'load_id': 1,
      'state': true,
      'duration_min': 1,
    },
  ),
  _LogEntry(
    time: '09:41:06',
    direction: '–',
    channel: 'MQTT',
    type: 'ACK',
    hint: 'v1/…/ack · Chờ nhận',
    summary: 'Chưa có ACK mẫu',
    topic: '$_basePath/ack',
  ),
];

const _filters = ['Telemetry', 'Command', 'ACK', 'Config', 'Status', 'BLE'];

class ConsoleScreen extends StatefulWidget {
  const ConsoleScreen({super.key, this.inShell = true, this.args});

  final bool inShell;
  final ConsoleArgs? args;

  @override
  State<ConsoleScreen> createState() => _ConsoleScreenState();
}

class _ConsoleScreenState extends State<ConsoleScreen> {
  var _entries = List<_LogEntry>.of(_sampleEntries);
  final _activeFilters = <String>{};
  bool _paused = false;
  bool _autoScroll = true;
  _LogEntry? _selected = _sampleEntries[4];

  List<_LogEntry> get _visible => _activeFilters.isEmpty
      ? _entries
      : _entries.where((e) => _activeFilters.contains(e.type)).toList();

  void _toggleFilter(String tag) {
    setState(() {
      if (!_activeFilters.remove(tag)) _activeFilters.add(tag);
    });
  }

  void _clear() {
    setState(() {
      _entries = [];
      _selected = null;
    });
  }

  @override
  Widget build(BuildContext context) {
    final visible = _visible;
    final selected = visible.contains(_selected) ? _selected : null;

    return ScreenScaffold(
      title: 'Console realtime',
      subtitle: 'Nhật ký kỹ thuật · Phiên minh họa',
      showBack: true,
      embedInTab: widget.inShell,
      navIndex: widget.inShell ? null : 1,
      onNavTap: widget.inShell ? null : (i) => AppRoutes.openTab(context, i),
      body: SingleChildScrollView(
        padding: const EdgeInsets.fromLTRB(16, 16, 16, 24),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            _DeviceInfoCard(
              name: widget.args?.name ?? 'Ao nuôi A1',
              deviceId: widget.args?.deviceId ?? 'esp32s3_912a',
            ),
            const SizedBox(height: 12),
            Wrap(
              spacing: 8,
              runSpacing: 8,
              children: [
                _TagChip(
                  label: 'Tất cả',
                  selected: _activeFilters.isEmpty,
                  onTap: () => setState(_activeFilters.clear),
                ),
                for (final tag in _filters)
                  _TagChip(
                    label: tag,
                    selected: _activeFilters.contains(tag),
                    onTap: () => _toggleFilter(tag),
                  ),
              ],
            ),
            const SizedBox(height: 12),
            _Toolbar(
              paused: _paused,
              autoScroll: _autoScroll,
              onPause: () => setState(() => _paused = !_paused),
              onClear: _clear,
              onAutoScroll: () => setState(() => _autoScroll = !_autoScroll),
            ),
            const SizedBox(height: 12),
            _ConsolePanel(
              entries: visible,
              selected: selected,
              onSelect: (e) => setState(() => _selected = e),
            ),
            if (selected != null) ...[
              const SizedBox(height: 12),
              _DetailCard(entry: selected),
            ],
            const SizedBox(height: 12),
            const Text(
              'Topic rút gọn theo thiết bị đã chọn; chi tiết hiển thị đường dẫn đầy đủ. Chỉ đọc bản tin mẫu, không gửi lệnh.',
              style: AppTextStyles.bodySecondary,
            ),
          ],
        ),
      ),
    );
  }
}

class _DeviceInfoCard extends StatelessWidget {
  const _DeviceInfoCard({required this.name, required this.deviceId});

  final String name;
  final String deviceId;

  @override
  Widget build(BuildContext context) {
    return AppCard(
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Expanded(child: Text(name, style: AppTextStyles.heading)),
              const StatusChip(label: 'Bản tin mẫu', kind: StatusKind.online),
            ],
          ),
          const SizedBox(height: 10),
          Text('device_id: $deviceId', style: AppTextStyles.mono),
          const Text('user_id: usr_99218472', style: AppTextStyles.mono),
          const SizedBox(height: 8),
          const Text(
            'ETH · Trực tuyến (mẫu) · Không có luồng trực tiếp',
            style: AppTextStyles.bodySecondary,
          ),
        ],
      ),
    );
  }
}

class _TagChip extends StatelessWidget {
  const _TagChip({
    required this.label,
    required this.selected,
    required this.onTap,
  });

  final String label;
  final bool selected;
  final VoidCallback onTap;

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      onTap: onTap,
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 9),
        decoration: BoxDecoration(
          color: selected ? AppColors.primary : AppColors.chipNeutral,
          borderRadius: BorderRadius.circular(22),
        ),
        child: Text(
          label,
          style: AppTextStyles.bodyMedium.copyWith(
            color: selected ? AppColors.textOnPrimary : AppColors.chipNeutralText,
            fontWeight: FontWeight.w600,
