import '../theme/app_colors.dart';
import '../theme/app_text_styles.dart';
import '../widgets/app_buttons.dart';
import '../widgets/app_card.dart';
import '../widgets/screen_scaffold.dart';

class ProvisionSuccessScreen extends StatefulWidget {
  const ProvisionSuccessScreen({super.key, required this.args});

  final ProvisionSuccessArgs args;

  @override
  State<ProvisionSuccessScreen> createState() => _ProvisionSuccessScreenState();
}

class _ProvisionSuccessScreenState extends State<ProvisionSuccessScreen> {
  @override
  void initState() {
    super.initState();
    // TODO: use the real values received from the ESP.
    WidgetsBinding.instance.addPostFrameCallback((_) {
      _registerDevice();
    });
  }

  Future<void> _registerDevice() async {
    try {
      await CrudApi.addDevice(
        userId: widget.args.userId,
        deviceMacAddress: widget.args.deviceId,
        defaultName: widget.args.deviceName,
        maxSensorCount: 4,
        maxLoadCount: 4,
        activeSensorCount: 0,
        internetMethod: 'ETH',
      );
      await MqttSessionManager.instance.startForUser(widget.args.userId);
      await MqttSessionManager.instance.addDevice(
        widget.args.deviceId,
        name: widget.args.deviceName,
      );
    } catch (error) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Không thể đăng ký thiết bị MQTT: $error')),
      );
    }
  }

  @override
  Widget build(BuildContext context) {
    return ScreenScaffold(
      title: 'Hoàn tất',
      subtitle: 'Bước 3/3 · Chờ thiết bị kết nối',
      showBack: true,
      body: SingleChildScrollView(
        padding: const EdgeInsets.fromLTRB(16, 28, 16, 24),
        child: Column(
          children: [
            Container(
              width: 72,
              height: 72,
              decoration: BoxDecoration(
                shape: BoxShape.circle,
                border: Border.all(color: AppColors.primary, width: 2),
              ),
              child: const Icon(
                Icons.check_rounded,
                color: AppColors.primary,
                size: 36,
              ),
            ),
            const SizedBox(height: 20),
            const Text(
              'Thiết lập cấu hình thành công',
              textAlign: TextAlign.center,
              style: AppTextStyles.heading,
            ),
            const SizedBox(height: 8),
            const Text(
              'Thiết bị đã lưu vào NVS và khởi động lại sau khoảng 2 giây.',
              textAlign: TextAlign.center,
              style: AppTextStyles.bodySecondary,
            ),
            const SizedBox(height: 22),
            const AppCard(
              child: Column(
                children: [
                  _StepRow(
                    icon: Icons.check_rounded,
                    label: 'Đã nhận cấu hình',
                    done: true,
                  ),
                  SizedBox(height: 12),
                  _StepRow(
                    icon: Icons.check_rounded,
                    label: 'Đã khởi động lại',
                    done: true,
                  ),
                  SizedBox(height: 12),
                  _StepRow(
                    icon: Icons.radio_button_unchecked,
                    label: 'Đang kết nối mạng',
                    done: false,
                  ),
                ],
              ),
            ),
            const SizedBox(height: 16),
            const GhostButton(label: 'Mở bảng điều khiển', onPressed: null),
            const SizedBox(height: 12),
            OutlineAppButton(
              label: 'Về danh sách thiết bị',
              onPressed: () {
                Navigator.of(
                  context,
                ).pushNamedAndRemoveUntil(AppRoutes.shell, (route) => false);
              },
            ),
          ],
        ),
      ),
    );
  }
}

class _StepRow extends StatelessWidget {
  const _StepRow({required this.icon, required this.label, required this.done});

  final IconData icon;
  final String label;
  final bool done;

  @override
  Widget build(BuildContext context) {
    return Row(
      children: [
        Icon(
          icon,
          size: 20,
          color: done ? AppColors.primary : AppColors.textSecondary,
        ),
        const SizedBox(width: 10),
        Text(label, style: AppTextStyles.body),
      ],
    );
  }
}

