    StreamCipher make() =>
        SICStreamCipher(AESEngine())
          ..init(true, ParametersWithIV(KeyParameter(key), iv));
    final data = Uint8List.fromList(List.generate(50, (i) => i));
    final whole = make().process(data);
    final c = make();
    final split = [
